window.READER_DATA={"title": "Yakan Istiaab", "slug": "yakan-istiaab", "pages": [{"n": 1, "paras": ["نحو وعي حركي إسلامي الاستيعاب في حياة الدعوة والدعاة", "فتحي يكن", "مؤسسة الرسالة مؤسسة الرسالة ناشرون"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0001.png"}, {"n": 2, "paras": ["الاستيعاب في حياة الدعوة والداعية", "فتحي يكن"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0002.png"}, {"n": 3, "paras": ["منتدى اقرأ الثقافي"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0003.png"}, {"n": 4, "paras": ["بسم الله الرحمن الرحيم", "الإهداء", "إلى الأخوة الدعاة، القائمين على ثغور الإسلام في كل مكان. إلى من أحب. أقدم بكل تواضع بعضاً مما أحب. فأسأل الله القبول. وعلى الله قصد السبيل", "فتحي"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0004.png"}, {"n": 5, "paras": ["المقدّمة", "هذا الكتاب هو في الحقيقة «محصلة معاناة» طويلة، وثمرة تجارب قاسية ومريرة عشتها أو عايشتها في واقع العمل الإسلامي في أكثر من قطر وأكثر من موقع .", "ولقد وضعت تصميمه خلال غيبة قسرية عن بلدي، ثم كانت كتابته خلال «إقامة شبه جبرية» في منطقة من مناطق بلدي، وخلال شهر رمضان المبارك من عام ١٤٠٢ ه الموافق لشهري (حزيران - تموز) من عام ١٩٨٢، يهمني منه أن يقرأ بأناة وتمعن، ويدرس بهدوء وتفكر، ليستفاد منه إن كان فيه ثمة ما يفيد، وآمل أن يكون جله مفيداً إن لم يكن كله كذلك . .", "كما أرجو تجاوز العثرات وبخاصة إن كانت شكلية أو"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0005.png"}, {"n": 6, "paras": ["فنية، والاستغراق في المعاني لا في المباني. وأن ينالني من قارئه - استفاد منه أم لم يستفد - دعوة صالحة هي وأيم الحق من أهم المطالب وأعظم المكاسب.", "سائلاً الله تعالى أن يجعلنا ممن يستمعون القول أو يقرأونه فيتبعون أحسنه. وإلى الله ترجع الأمور", "الضنية - بقاع صفرين رمضان ١٤٠٢ ه حزيران - تموز ١٩٨٢", "المؤلف"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0006.png"}, {"n": 7, "paras": ["الاستيعاب في الدعوة والداعية", "ماذا أعني بالاستيعاب؟ أعني بالاستيعاب، قدرة الدعاة على اجتذاب الناس وربحهم على اختلاف عقولهم وأمزجتهم وطبقاتهم وثقافاتهم الخ.", "فالناس يختلفون اختلافاً نوعياً في كل شيء. في نمط التفكير، في مستوى العيش، في مركب المزاج، في معيار الذكاء، وفي كافة القدرات الحسية والنفسية.", "والداعية الناجح هو القادر على الإيغال والتأثير بدعوته وفكرته في الناس كل الناس، على اختلاف مشاربهم وطبائعهم ومستوياتهم. وعلى اجتذاب مساحة كبرى من الجماهير واستيعابها فكرياً وحركياً."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0007.png"}, {"n": 8, "paras": ["وبذلك يكون الاستيعاب قدرة شخصية، ومؤهلة خلقية، وصفة إيمانية، ومنة ربانية، تساعد الدعاة وتجعلهم منارات هدى في مجتمعاتهم، وأقطاب رحى في مواطنهم يستقطبون الناس، ويلتف من حولهم الناس..", "والحقيقة.. إن القدرة على الاستيعاب تعتبر المؤهل الأول والأهم في شخصية الداعية. وبدونها لا يكون داعية ولا تكون دعوة..", "تفاوت القدرة على الاستيعاب: والذي لا شك فيه أن الدعاة كبقية الناس يتفاوتون في قدراتهم على الاستيعاب. ولكن الذي لا بد منه كذلك أن يتمتع كل داعية بحد أدنى من القدرة على الاستيعاب، لأنه بغيرها لا يكون داعية أو عاملاً في اطار الدعوة.", "إن عدم توفر الحد الأدنى من القدرة على الاستيعاب قد لا تجعل الداعية عقيم الإنتاج عديم الفائدة فحسب، بل قد تجعله مسيئاً للإنتاج، مسبباً الضرر للإسلام والحركة على حد سواء.", "فكم من أناس - اعتبروا دعاة أو عاملين في الحقل الإسلامي - أضروا ولم ينفعوا، وهدموا ولم يبنوا، ونفروا"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0008.png"}, {"n": 9, "paras": ["ولم يبشروا، وكانوا حجة على الدعوة بين أبنائها وأعدائها. وكم من آخرين عاشوا في أجواء الدعوة ونهلوا من مبادئها ولكن دون أن ينقلوا أجواءها ومبادءها خطوة واحدة خارج إطارها.", "وهناك آخرون كانوا في الدعوة وكانت بهم الدعوة، وعاشوا فيها وعاشت بهم. أولئك هم الدعاة حقاً وأولئك هم رجالها والذين يحتاج الإسلام إليهم وإلى أمثالهم لرفع رايته وبناء دولته، وإقامة حجته على العالمين.", "وتفاوت القدرة على الاستيعاب في الناس كتفاوت القدرة على ذلك في الآنية. فهنالك إناء واحد يمكن أن يستوعب ما لا تستوعبه مئات الآنية الأخرى، كما أن هنالك داعية يمكن ان يستوعب من الناس ما لا يقدر على استيعابه مئات العاملين في الحقل الإسلامي.", "ففي معرض الاشارة النبوية إلى تفاوت أثر العلماء - مثلاً - في استيعاب الناس، روى معاذ بن جبل رضي الله عنه، عن رسول الله ﷺ أنه قال: «تعلموا العلم، فإن تعلمه لله خشية، وطلبه عبادة، ومذاكرته تسبيح، والبحث عنه جهاد، وتعليمه لمن لا يعلمه صدقة، وبذله لأهله قربة."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0009.png"}, {"n": 10, "paras": ["لأنه معالم الحلال والحرام، ومنار سبل أهل الجنة، وهو الأنيس في الوحشة، والصاحب في الغربة، والمحدث في الخلوة، والدليل على السراء والضراء، والسلاح على الأعداء، والزين عند الأخلاء. يرفع الله به أقواماً فيجعلهم في الخير قادة قائمة تقتص آثارهم، ويقتدى بفعالهم، وينتهى إلى رأيهم. ترغب الملائكة في خلتهم، وبأجنحتها تمسحهم، ويستغفر لهم كل رطب ويابس وحيتان البحر وهوامه، وسباع البر وأنعامه. لأن العلم حياة القلوب من الجهل، ومصابيح الأبصار من الظلم، يبلغ العبد بالعلم منازل الأخيار والدرجات العلى في الدنيا والآخرة». الحديث (١)", "وفي حديث آخر رواه أبو موسى الأشعري رضي الله عنه قال: قال رسول الله ﷺ: «مثل ما بعثني الله به من الهدى والعلم، كمثل غيث أصاب أرضاً، فكانت منها طائفة طيبة قبلت الماء، وأنبتت الكلأ والعشب الكثير. وكان منها أجادب أمسكت الماء فنفع الله بها الناس فشربوا وسقوا وزرعوا. وأصاب طائفة أخرى منها، إنما هي قيعان لا تمسك ماء ولا تنبت كلأ فذلك مثل من فقه في دين الله تعالى ونفعه ما بعثني الله به فعلم وعلم، ومثل من لم يرفع", "(١) رواه ابن عبد البر في كتاب العلم."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0010.png"}, {"n": 11, "paras": ["بذلك رأساً ولم يقبل هدى الله الذي أرسلت به»(١)", "الاستيعاب ونجاح الدعوة: والعلاقة بين الاستيعاب ونجاح الدعوة علاقة جذرية، إذ لا نجاح بدون قدرة على الاستيعاب. والدعوة الغنية بالدعاة القادرين على اجتذاب الناس إلى الإسلام وإلى الحركة يصبح حظها من النجاح ومن تحقيق أهدافها قوياً إذا ما توفرت لها المناخات اللازمة والشروط الأخرى.", "وعكس ذلك - كذلك - حيث أن الدعوة الفقيرة بالدعاة القادرين على استيعاب من حولهم قد تبقى عقيمة محدودة الانتشار والآثار إلى أن يقيض الله لها رجالاً تتوافر لديهم أسباب الهداية والتأثير والاستيعاب، أو يستبدلها بدعوة أخرى لا تكون مثلها، وتلك سنة الله ﴿ولن تجد لسنة الله تبديلاً﴾، ﴿ولن تجد لسنة الله تحويلاً﴾. وصدق الله تعالى حيث يقول: ﴿وإن تتولوا يستبدل قوماً غيركم ثم لا يكونوا أمثالكم﴾.", "الاستيعاب الخارجي والداخلي: أعني بالاستيعاب الخارجي استيعاب من هم خارج", "(١) رواه البخاري ومسلم."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0011.png"}, {"n": 12, "paras": ["الدعوة والحركة والتنظيم أي قبل مرحلة الانتماء والانتظام. أما الاستيعاب الداخلي فهو استيعاب الناس داخل التنظيم، أي استيعاب المنتظمين والملتحقين بالعمل الإسلامي والحركة.", "إن كلا المجالين يتمم بعضه بعضاً. وكلاهما مهم ويحتاج إلى قدرة فائقة على الاستيعاب. ونجاح الدعوة والداعية مشروط بامتلاك زمام المجالين والتفوق في المحيطين معاً، إذ لا قيمة للاستيعاب الخارجي إن لم يلازمه استيعاب داخلي.", "إن الاستيعاب الخارجي أشبه بتسوق المواد الخام وتهيئتها وتحضيرها من أجل أن تبدأ مرحلة جديدة هي مرحلة صناعتها وتصنيعها. وعملية الاستيعاب الداخلي - أي التصنيع - هي التي تحفظ الخامات من التلف وهي بالتالي التي تعطيها القيمة حيث تصبح قادرة على أن توظف في مجالات العمل الإسلامي المختلفة.", "وإلا فما قيمة أطنان من الحديد والاسمنت والرمل إن لم تتوفر (ورشة) العمل التي تحيلها أبنية وجسوراً ومرافق عامة؟؟ وما قيمة أكداس من الخضار والزيوت والأسمان والحبوب إن لم يتوفر الطهاة الذين يصنعون منها الأطعمة والمآكل الشهية!!"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0012.png"}, {"n": 13, "paras": ["من هنا يمكن القول بأن الاستيعاب الخارجي هو عمل استقصائي توجيهي تحضيري، في حين أن الاستيعاب الداخلي هو عمل تكويني تصنيعي أساسي. وإن لكل مجال من هذين المجالين متطلبات وشروطاً تبعاً لمهمة وأهداف كل منهما.", "الاستيعاب الخارجي", "إن حمل الدعوة إلى الناس وجعلهم يؤمنون بها ويثقون ويتأثرون، ومن ثم يلتحقون ويعملون ويجاهدون ويضحون، عملية صعبة وشاقة وتحتاج إلى قدرات ومتطلبات مختلفة. .", "ومن توفرت فيه هذه الشروط أو أكثرها كان داعية موفقاً ناجحاً قادراً على استيعاب الناس واستقطابهم حول الإسلام وحول الدعوة. وبقدر تكاثر هذه العينات من الدعاة بقدر ما يكون استيعاب الدعوة للناس أكبر، وأثرها فيهم أبعد وأكثر. .", "ومن خلال كتاب الله تعالى الذي لا يأتيه الباطل من بين يديه ولا من خلفه، وفي ضوء السنة النبوية الشريفة، يمكننا تحديد أبرز المتطلبات التي يحتاجها الدعاة في عملية الاستيعاب والاستقطاب هذه."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0013.png"}, {"n": 14, "paras": ["أولاً الفقه في دين الله", "إن الأخ المسلم كيما يكون داعية إلى الله بحق، مستقيماً على الصراط راشداً مسترشداً يحتاج أولاً وقبل كل شيء إلى قدر مقبول من الفقه في دين الله . .", "فاستبانة الحلال من الحرام والخير من الشر، ومعرفة الفرائض والواجبات والسنن والعقائد والأحكام - وهي المنارات الهادية على طريق الدعوة والداعية - تحتاج كلها الى فقه في الإسلام .", "من هنا جاءت التوجيهات القرآنية والنبوية تلفتان إلى قيمة الفقه وتحضان عليه . .", "فمن كتاب الله قوله تعالى: ﴿قل هل يستوي الذين يعلمون والذين لا يعلمون﴾(١) وقوله: ﴿ويرى الذين أوتوا العلم الذي أنزل إليك من ربك هو الحق ويهدي إلى", "(١) سورة الزمر، ٩"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0014.png"}, {"n": 15, "paras": ["صراط العزيز الحميد(١) وقوله: ﴿ثم جعلناك على شريعة من الأمر فاتبعها ولا تتبع أهواء الذين لا يعلمون﴾(٢).", "ومن مشكاة النبوة قوله ﷺ: «يا أيها الناس: إنما العلم بالتعلم، والفقه بالتفقه، ومن يرد الله به خيراً يفقهه في الدين، وإنما يخشى الله من عباده العلماء»(٣)، وقوله: «إذا أراد الله بعبد خيراً فَقَّهَهُ في الدين وألهمه رشده»(٤)، وقوله: «إن مثل العلماء في الأرض كمثل النجوم يهتدى بها في ظلمات البر والبحر، فإذا انطمست النجوم أوشك أن تضل الهداة»(٥).", "ثم هل يمكن أن يكون الداعية داعية إلى الله بصدق وعلى هدى إن لم يكن فقه في دين الله؟؟", "وهل يمكن أن يستوعب الداعية الناس في الإسلام إن كان جاهلاً لمبادىء الإسلام وأصوله وقواعده وأحكامه وتشريعاته وحلاله وحرامه؟", "إن اجتذاب الناس إلى الإسلام أولاً هو الأساس وهو", "(١) سورة سبأ ، ٦", "(٢) سورة الجاثية، ١٨", "(٣) رواه البخاري.", "(٤) رواه الطبراني.", "(٥) رواه أحمد."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0015.png"}, {"n": 16, "paras": ["الطريق الصحيح حيث يجعلهم مسلمين مرتبطين بالإسلام متشبتين به كائناً ما كانت الظروف، في حين أن اجتذابهم إلى الحركة أولاً سيجعل ولاءهم للتنظيم وللحركة وليس لشرع الله..", "ولقد ابتلي الإسلام اليوم بدعاة يدعون الناس إلى تنظيماتهم بدل أن يدعوهم إلى الإسلام.. ويبينون لهم محاسن تنظيماتهم ومزاياها بدل أن يبينوا محاسن الإسلام ومزاياه.. وهذا ما جعل ارتباط الفرد بالدعوة ارتباطاً حزبياً وليس ارتباطاً عقائدياً، بل وجعله في بعض الأحيان ارتباطاً شخصياً وليس مبدئياً.. وهذا بالتالي جعل ميدان الدعوة الإسلامية غاصاً بالتنظيمات والأحزاب والفرق والحركات..", "إن معظم ذلك مرده إلى جهل بحقيقة هذا الدين، وبالتالي إلى عدم الالتزام بأحكامه وقواعده. والنتيجة كما نرى وكما أخبر عنها رسول الله ﷺ بقوله: «إن الله لا ينتزع العلم انتزاعاً ولكن ينتزعه بقبض العلماء، حتى إذا لم يبق عالم قط، اتخذ الناس رؤوساً جهالاً فسئلوا فأفتوا بغير علم فضلوا وأضلوا»(١)، وصدق رسول الله ﷺ حيث يقول: «قليل العلم خير من كثير العبادة. وكفى بالمرء فقهاً إذا عبد الله. وكفى بالمرء جهلاً إذا أعجب برأيه»(٢).", "(١) رواه الشيخان.", "(٢) رواه الطبراني في الأوسط."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0016.png"}, {"n": 17, "paras": ["إن الداعية معرض لأن يستفتى ويسأل عن أمور كثيرة فهل يفتي ويجيب برأيه أم بالإسلام؟ فإن كان جاهلاً بدين الله فهل تنعقد له الإمامة على المسلمين ويكون له الأثر فيهم؟", "ثم إنه قبل هذا. هل يمكن أن يكون قدوة للناس بعمله إن لم يكن علم بشريعة الإسلام. وهل يكون العمل بالشريعة من غير علم للشريعة. ؟", "إن الفقه في دين الله والمعرفة العامة تمكنان الداعية من مخاطبة الناس على قدر عقولهم، بعد معرفته لعقولهم، ومن ملامسة قلوبهم، بعد معرفة ما يخالجها وما يساورها.", "والداعية الذي لا يملك من المفاتيح ما يفتح به العقول والقلوب لن يتمكن من اجتذاب أصحابها واستيعابهم، وستبقى دعوته لهم صيحة في واد ونفخة في رماد.", "ومن الفقه في دين الله التزود بالثقافات والمعارف المختلفة والتي من شأنها أن تساعد الداعية على اجتذاب كل الناس على مختلف ثقافاتهم وميولهم، وبخاصة في عصر تعددت فيه الاتجاهات وكثرت الفلسفات وغدا التأثير في الناس واجتذابهم ليس بالأمر السهل، بل ويحول دونه مائة سؤال وسؤال وألف شبهة وشبهة، مصداقاً لقوله"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0017.png"}, {"n": 18, "paras": ["تعالى: ﴿أو كظلمات في بحر لجي يغشاه موج من فوقه موج، من فوقه سحاب، ظلمات بعضها فوق بعض، إذا أخرج يده لم يكد يراها، ومن لم يجعل الله له نوراً فما له من نور﴾.", "أعرف بعض الدعاة ممن يعملون في المجالات السياسية والعامة وهم مقطوعوا الصلة تماماً بالثقافة والفكر الإسلاميين، وليسوا على شيء من الفقه في دين الله. فهل يمكن أن نتصور كيف يمكن أن يسلكوا بعملهم السياسي الصراط السوي، وأن يصب عملهم هذا في خدمة الإسلام ولمصلحته؟؟", "ثم إن عملية اقناع الناس بالإسلام واجتذابهم إليه واستنقاذهم من براثن الأفكار والتصورات التي يحملونها، كما أن عملية اقتحام عقولهم ونفوسهم، وحل مشاكلهم العقلية والنفسية كلها إلى ثقافة وخبرة ومهارة. والداعية بحاجة ماسة إلى نصيب كبير منها جميعاً في عملية الدعوة والاستيعاب.", "إن اقتحام العقول والنفوس أصعب بكثير من اقتحام المواقع والثغور. وإذا كانت تلك تحتاج إلى معدات مختلفة ومهارات فائقة وخبرات واسعة، فإن هذه تحتاج إلى أكثر في كل المجالات."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0018.png"}, {"n": 19, "paras": ["في الحرب يواجه الجندي عدواً واحداً في مواقع محددة وبأسلحة محددة. أما في عمل الدعوة فيواجه الداعية أنواعاً شتى من الخصوم والأعداء بأسلحة شتى وأساليب شتى، كما يواجه مرضى بعلل شتى ومعقدين من مشكلات شتى.", "فهذا ماركسي. وذاك قومي. وغيره هيبي أو اشتراكي أو رأسمالي أو علماني إلى ما لا نهاية له من الانتماءات الأخرى.", "وهذا عالم مغرور بعلمه. وذاك جاهل ويجهل أنه جاهل. والآخر غبي أو ذكي. الخ.", "وهذا مريض نفسياً. وغيره مريض جنسياً. وسواه مريض عاطفياً. وآخر مريض عصبياً الخ.", "وهذا غني أبطره غناه، والآخر فقير سحقه فقره أو جعله حاقداً على الناس جميعاً، وغيره زاهد في الدنيا متخل عنها لأعداء الله.", "وهذا عائلي النزعة. وسواه عرقي الطلعة. والآخر عشائري الشرعة.", "وهذا جريء إلى حد التهور. وسواه جبان. وما بينهما من الطباع أشكال وألوان. ."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0019.png"}, {"n": 20, "paras": ["وهكذا يجد الداعية نفسه في مستشفى كبير يغص بالمرضى والمعاقين والمشوهين والمعقدين. وهذا ميدانه وهذه مسؤوليته وقدره.. وهو يحتاج أول ما يحتاج لسلوك هذا الطريق بعد الإيمان بالله والثقة به والاتكال عليه إلى قدر من العلم والثقافة والدراية والفكر والخبرة والاطلاع لأنها جميعاً تعينه على ملامسة الداء بالدواء اللازم، ومواجهة المشكلة بالحل الحاسم، وبغير ذلك سيخبط خبط عشواء، ويزيد الطين بلة والمشكلة تعقيداً ولا حول ولا قوة إلا بالله.", "ثانياً القدوة الحسنة", "والداعية لا بد وأن يكون قدوة حسنة في الناس كيما يتمكن من التأثير فيهم واستقطابهم واستيعابهم. فالناس لا يتأثرون بلسان المقال بقدر ما يتأثرون بلسان الحال. فالذي يدعو الناس إلى مكارم الأخلاق وأخلاقه سيئة لن تكون دعوته مستجابة ولن يلقى إلا الصد والأعراض. والذي يدعو الناس إلى الجهاد في سبيل الله دون أن يكون مجاهداً أو على ثغرة من ثغور الجهاد لن يتجاوب الناس مع دعوته وادعاءاته.."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0020.png"}, {"n": 21, "paras": ["والذي يحض الناس على البذل والتضحية والعطاء وهو شحيح لن يلقى أذناً صاغية في الناس أجمعين.", "والذي يدعو الناس إلى التواضع وهو مختال فخور، وإلى الايثار وهو صاحب أثرة، وإلى الصدق وهو كذاب، وإلى الأمانة وهو خائن، وإلى الاستقامة وهو منحرف، وإلى الطاعة وهو عاص، وإلى التماس الحلال الطيب وهو غارق في المحرمات والخبائث. إن إنساناً كذلك قد يتمكن من خداع الناس حيناً ولكنه لن يتمكن من خداعهم في كل حين.", "أعرف إنساناً من أصحاب العمائم بل كان صاحب العممة الوحيد في قريته. كانوا ينتظرون عودته من الدراسة الشرعية بفارغ الصبر ليكون فيهم إماماً ولهم مرجعاً. وعندما عاد تمنوا لو أنه لم يعد. كان لسانه فيهم سليطاً بذيئاً، لا يتورع عن التلفظ بأبذأ العبارات، وعن أكل أموال الناس بالباطل. حتى بلغ به السوء أنه خرج مع رفيقين له من أبناء القرية لجمع التبرعات من بلد عربي، وحدثني أحدهما قائلاً: قبل أن تهبط بنا الطائرة في البلد المقصود التفت إلينا (صاحب العممة) قائلاً: أود أن تعلموا منذ الآن أنني سأقتطع لنفسي نصف التبرعات ولكما الربع، والمتبقي يكون لمشروع بناء المسجد. والتفت إليه محدثي قائلاً:"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0021.png"}, {"n": 22, "paras": ["ألا تتقي الله يا شيخ وأنت بين يديه وهو القادر على أن يجعلك رماداً في أقل من لحظة..", "المهم أن هذا الرجل عندما تكشفت لقريته أخلاقه نبذه الناس فارتحل إلى المدينة. وفي المدينة استمر على نفس السيرة والسريرة دون أن يتعظ، فنبذه الناس، فارتحل إلى بلد أجنبي بعيد. وأدخل في روع الجالية الإسلامية هناك أنه إمام المسلمين بلا منازع قبل أن يكشفوا حقيقته ويكتشفوا أمره.. والقصة مليئة بالشجون..", "إن أمثال هذه الرجل في الناس كثير، وهذا ما جعل هؤلاء حجة لضعفاء الإيمان على الإسلام وعلى الدعوة، بل وجعل أعمالهم ذريعة للمترخصين وفتنة للكثيرين، ولا حول ولا قوة إلا بالله العلي العظيم.", "إن استقامة الداعية هي سر نجاح دعوته، وهي المؤهل الأهم لإمامته، وهي العامل الأقوى في هدايته. وصدق الله تعالى حيث يقول ﴿فلذلك فادع واستقم كما أمرت﴾(١).", "والقرآن الكريم يذخر بتهديد ووعيد من يخالف فعله قوله، والذين يقولون ما لا يفعلون.", "(١) سورة الشورى، ١٥"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0022.png"}, {"n": 23, "paras": ["يقول الله تعالى : ﴿يا أيها الذين آمنوا لم تقولون ما لا تفعلون، كبر مقتاً عند الله أن تقولوا ما لا تفعلون﴾(١) ﴿أتأمرون الناس بالبر وتنسون أنفسكم وأنتم تتلون الكتاب أفلا تعقلون﴾(٢) وفي كتب الحديث عشرات الروايات التي تحض على تطابق الظاهر مع الباطن، والقول مع الفعل.. كما تنذر وتحذر المعرضين عن ذلك بالعواقب الوخيمة والعقوبات العظيمة..", "يقول رسول الله ﷺ «ما آمن بالقرآن من استحل محارمه»(٣). «إن أناساً من أهل الجنة ينطلقون إلى أناس من أهل النار، فيقولون: بم دخلتم النار، فوالله ما دخلنا الجنة إلا بما تعلمناه منكم.. فيقولون: إنا كنا نقول ولا نفعل»(٤) «مثل الذي يعلم الناس الخير وينسى نفسه كمثل", "(١) سورة الصف، ٢ و٣", "(٢) سورة البقرة، ٤٤.", "(٣) رواه الترمذي.", "(٤) رواه الطبراني."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0023.png"}, {"n": 24, "paras": ["السراج يضيء للناس ويحرق نفسه»(١)", "«إني لا أتخوف على أمتي مؤمناً ولا مشركاً.. فأما المؤمن فيحجزه إيمانه، وأما المشرك فيقمعه كفره. ولكن أتخوف عليكم منافقاً عالم اللسان، يقول ما تعرفون، ويعمل ما تنكرون»(٢)", "«إن الرجل لا يكون مؤمناً حتى يكون قلبه مع لسانه سواء، ويكون لسانه مع قلبه سواء، ولا يخالف قوله عمله، ويأمن جاره بوائقه»(٣)", "إن الدعوة الإسلامية حين تبتلى بأشخاص من هذا الشكل تصبح معرضة للبوار. أناس فيها يبنون والآخرون يهدمون، وأناس يجمعون وآخرون يفرقون، وآخرون يحبون وغيرهم يكرهون.", "من هنا وجب على الدعوة أن تنقي صفوفها من مرضى الانفصام كائناً ما كانت مراكزهم ومراتبهم، وكائناً ما كانت قدراتهم التنظيمية والإدارية والفكرية، لأن ضررهم سيكون أكبر من نفعهم، ويكفي أنها لن تكون بهم على هدى من", "(١) رواه الطبراني", "(٢) رواه الطبراني.", "(٣) رواه الأصبهاني."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0024.png"}, {"n": 25, "paras": ["الله وتوفيق. ﴿ومن لم يجعل الله له نوراً فما له من نور﴾.", "ثالثاً الصبر", "واجتذاب الناس واستيعابهم يحتاج من الداعية إلى صبر عليهم لا إلى ضيق بهم وتبرم منهم..", "فالناس أصحاب أمزجة شتى وعيوب شتى وطباع شتى وحاجات ومصالح شتى.. والناس مشاكلهم كثيرة وهمومهم كبيرة يحتاجون إلى من يتسع لهم.", "والناس غير مؤدبين بأدب الإسلام، وغير متخلقين بخلق القرآن، وهم بمسيس الحاجة إلى من يعايشهم ويتعايش معهم ليسبر أغوارهم ويعالج أمراضهم، وهذا يحتاج إلى صبر طويل..", "والهداية لا يمكن أن تأخذ طريقها إلى نفوس الناس وقلوبهم دفعة واحدة، ولا بد لذلك من زمن ومتابعة وجهود تبذل لتؤتي أكلها بإذن ربها. وهذا يحتاج كذلك إلى صبر.", "والناس أصحاب حاجات مختلفة، ومنهم من لا يرى"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0025.png"}, {"n": 26, "paras": ["في الكون حاجة أهم من حاجته، وصاحب الحاجة أرعن، قد لا يلقي بالأ إلا ما يقول لك، وقد لا يبالي بالساعة التي يقرع فيها بابك، من غير موعد أو إشعار، وقد تكون هذه الزيارة في وقت طعامك أو منامك أو راحتك، وهذا يحتاج لتحمله إلى صبر مع التوجيه الناعم ولفت النظر، وإلا وقعت بينك وبينه الواقعة، وانقلب عدواً حاقداً لا يرعى إلا ولا ذمة. .", "أعرف بعض العاملين في الحقل الإسلامي لا يستقبلون الناس إلا ضمن مواعيد مسبقة، فإن جاءهم من ليس على موعد صرفوه، أو قال لهم أهله أنه ليس موجوداً، وهو يعلم أنه موجود. وتصور عندئذ كيف ستكون النتيجة. . وأعرف آخرين يعطلون (الهاتف) أثناء قيلولتهم وليكن من بعد ذلك الطوفان. وآخرون يمتنعون بالمرة عن استقبال أصناف من الناس لمعرفتهم المسبقة بأنهم متعبون. .", "إن هؤلاء وأولئك قد يكونوا معذورين من قريب أو بعيد، ولكن الشيء الذي لا خلاف فيه هو أنهم في الدعوة فاشلون، وأن الناس عنهم سيعرضون.", "إن الداعية بحق هو الذي يعيش لغيره لا لنفسه، وتهمه سعادة غيره ولو على حساب سعادته هو، ويتجرع"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0026.png"}, {"n": 27, "paras": ["الغيظ في ذلك وهو على يقين بأنه سيتحول في جوفه إيماناً، وسيكون له ذخراً عند الله يوم الحساب. وصدق إمام الصابرين محمد حيث يقول: «ما من جرعة أحب إلى الله من جرعة غيظ كظمها عبد، ما كظمها عبد لله إلا ملأ الله بها جوفه إيماناً»(١)", "إن نقل إنسان من الضلال إلى الهدى، والأخذ بيد إنسان من الظلمات إلى النور، ليس له هذا الأجر الجزيل عند الله والمثوبة العظمى يوم القيامة - كما جاءت به أحاديث كثيرة - لولا أن هذه العملية تحتاج من الداعية إلى صبر طويل وتحمل واحتمال.", "فقد تحتاج إلى أن تصرف معه أوقاتاً طويلة من أوقات عملك أو راحتك. وقد تحتاج إلى أن تسمع له وتنصت، وتنصح له وتذكر، وتزوره وتهاديه، كل ذلك من غير ملل أو تبرم أو ما يشعره منك بذلك، فإن وقع ذلك حبط العمل وفشلت المحاولة وذهبت الجهود سدى.", "أعرف أحد الدعاة الموفقين الذين يتقربون إلى الله بصبرهم على متاعب الآخرين، وبخاصة أن كل ذلك طريقاً إلى هداية هؤلاء والأخذ بأيديهم إلى واحة الإسلام. وكان", "(١) رواه ابن ماجه."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0027.png"}, {"n": 28, "paras": ["لهذا الداعية قريب أدمن الخمرة إدماناً مفرطاً جعله منبوذاً من عائلته ومحيطه، لا يكاد يجد بيتاً يؤويه، أو إنساناً يكلمه إلا من كان على شاكلته.", "ومرة قرع الباب على (الداعية) ولما فتح وجد نفسه وجهاً لوجه أمام ذلك المنبوذ والذي يكبره بعشرات السنوات. وبحنو الهداية طلب منه الدخول، فدخل الرجل متعثراً بخطاه مستغرباً هذا الصنيع وقد تعود أن تركله الأقدام خارج البيوت، ويقذف في وجهه البصاق بلا حساب.", "دخل الرجل، وبدأت بدخوله مسيرة الصبر الطويلة أياماً وأسابيع إلى أن أشرقت شمس الإيمان في قلبه، وبدأت ثمار الهداية تؤتي أكلها فيه بإذن ربها.", "صلح الرجل وحسن إسلامه وأصبح ملازماً للداعية لا يكاد يفارقه. إلى أن حدث ما لم يكن بالحسبان. فقد أدخل (الداعية) مستشفى لاجراء جراحة عاجلة. ولقد أجريت الجراحة بالفعل كان الرجل المهتدي خلالها على أعصابه يردد الدعوات ويصعد العبرات من شدة خوفه على من كان سبباً في هدايته. ولقد أقسم أن يبقى قرب سريره ليل نهار يخدمه بعينيه ويرد له بعض ما عليه. وأخيراً كانت الطامة حين منع الرجل من الدخول إلى غرفة الداعية بعد"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0028.png"}, {"n": 29, "paras": ["العملية. وعندما جاء مستفسراً محتجاً على ذلك صفعه كبير أصحاب الداعية على وجهه صفعة قوية، كانت كافية لهدم كل شيء، ولتحويل هذا الإنسان الذي حطمت بلحظة واحدة مشاعره وأحاسيسه إلى عدو للإسلام والمسلمين.", "من هنا كان طريق هداية الناس طريقاً صعباً على النفوس الضعيفة، والإرادات العاجزة، والذين لم يؤتوا حظاً من الصبر ونصيباً من سعة الصدر.", "ومن هنا جاءت الآيات الكريمة والأحاديث الشريفة تحض على الصبر وتعرض لمقام الصابرين:", "فمن كتاب الله قوله تعالى:", "﴿واستعينوا بالصبر والصلاة﴾(١)، ﴿فاصبر على ما يقولون﴾(٢)، ﴿وبشر المخبتين، الذين إذا ذكر الله وجلت قلوبهم والصابرين على ما أصابهم﴾(٣)، ﴿يا أيها الذين آمنوا اصبروا وصابروا ورابطوا واتقوا الله لعلكم", "(١) سورة البقرة، ٤٥.", "(٢) سورة طه، ١٣٠.", "(٣) سورة الحج، ٣٤ - ٣٥."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0029.png"}, {"n": 30, "paras": ["تفلحون(١)، ﴿إن الله مع الصابرين﴾(٢)، ﴿وبشر الصابرين﴾(٣)، ﴿إنما يوفى الصابرون أجرهم بغير حساب﴾(٤).", "﴿أولئك يؤتون أجرهم مرتين بما صبروا﴾(٥)، ﴿وجعلنا منهم أئمة يهدون بأمرنا لما صبروا﴾(٦).", "﴿ولنجزين الذين صبروا أجرهم بأحسن ما كانوا يعملون﴾(٧).", "ومن مشكاة النبوة في الصبر يقول رسول الله ﷺ: «الصبر معول المسلم». «ما رزق الله عبداً خيراً له ولا أوسع من الصبر»(٨). «ومن يتصبر يصبره الله، وما أعطي أحد عطاء خيراً وأوسع من الصبر»(٩).", "«الذي يخالط الناس ويصبر على أذاهم خير من الذي لا يخالط الناس ولا يصبر على أذاهم». «الصبر شطر الإيمان».", "(١) سورة آل عمران، ٢٠٠", "(٢) سورة البقرة، ١٥٣", "(٣) سورة البقرة، ١٥٥", "(٤) سورة الزمر، ١٠", "(٥) سورة القصص، ٤", "(٦) سورة السجدة، ٢٤", "(٧) سورة النحل، ٩٦", "(٨) رواه الحاكم", "(٩) رواه البخاري ومسلم"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0030.png"}, {"n": 31, "paras": ["وعن ابن المسيب رضي الله عنه قال: بينما رسول الله ﷺ جالس، ومعه أصحابه، وقع رجل بأبي بكر رضي الله عنه فآذاه، فصمت عنه أبو بكر. ثم آذاه الثانية، فصمت عنه أبو بكر، ثم آذاه الثالثة فانتصر أبو بكر. فقام رسول الله ﷺ، فقال أبو بكر: أوجدت علي يا رسول الله. فقال رسول الله ﷺ: نزل ملك من السماء يكذبه بما قال لك. فلما انتصرت ذهب الملك، وقعد الشيطان، فلم أكن لأجلس إذن مع الشيطان»(١). «ما من جرعة أعظم عند الله من جرعة غيظ، كظمها عبد ابتغاء وجه الله»(٢).", "رابعاً الحلم والرفق", "واستيعاب الناس يحتاج من الداعية إلى أن يكون حليماً عليهم رفيقاً بهم.. فالناس يمقتون العنف وأصحابه وينفرون من القسوة وأهلها. وصدق الله تعالى حيث يقول: ﴿ولو", "(١) رواه أبو داود.", "(٢) رواه ابن ماجة."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0031.png"}, {"n": 32, "paras": ["كنت فظاً غليظ القلب لانفضوا من حولك، فاعف عنهم واستغفر لهم وشاورهم في الأمر (١)", "فالداعية لا تكون دعوته بحمل الأفكار والنظريات المجردة إلى من حوله قبلوها أم رفضوها، وإنما بأن يعيش هذه الأفكار ويترجمها لهم على أرض الواقع أفعالاً وأخلاقاً وممارسات.", "والداعية لا تكون دعوته بمفاصلة الناس وإقامة الحجة عليهم، وإنما بأخذ كافة الأسباب التي تؤدي إلى هدايتهم.", "فهو من موقع الحب والغيرة عليهم والرحمة بهم يكابد من أجل استنقاذهم من حمأة الجاهلية وشقوتها إلى نعيم الإسلام. ولذلك فهو لا يسارع إلى مدابرتهم ومقاطعتهم ومفاصلتهم، وهذا كله يحتاج منه إلى حلم ورفق.", "إن على الداعية أن يعتبر نفسه مربياً للناس ومعلماً لهم، وإن عليه ليكون ناجحاً في تربيته وتعليمه أن لا يعاملهم كأنداد، وأن لا يتعامل معهم كند. وهو إن فعل ذلك أصبح مثلهم وفقد عنصر القوامة عليهم.", "(١) سورة آل عمران، ١٥٩"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0032.png"}, {"n": 33, "paras": ["فالداعية معني أولاً وقبل كل الناس بقوله تعالى: ﴿ادفع بالتي هي أحسن فإذا الذي بينك وبينه عداوة كأنه ولي حميم﴾(١)", "والداعية معني قبل غيره بقوله تعالى: ﴿الذين ينفقون في السراء والضراء والكاظمين الغيظ والعافين عن الناس والله يحب المحسنين﴾(٢)", "ومن أولى من الداعية بتحقيق قوله تعالى: ﴿ثم كان من الذين آمنوا وتواصوا بالصبر وتواصوا بالمرحمة﴾(٣)، وقوله: ﴿وعباد الرحمن الذين يمشون على الأرض هوناً، وإذا خاطبهم الجاهلون قالوا سلاماً﴾(٤)", "والداعية الأول ﷺ، كان أحلم الناس وأرفق الناس وهذا ما فتح قلوب الناس له وجعلهم يدخلون في دين الله أفواجاً..", "وكان ﷺ يعلم أصحابه بأقواله وأفعاله الحلم على الناس والرفق بهم:", "(١) سورة فصلت، ٣٤.", "(٢) سورة آل عمران، ١٣٤.", "(٣) سورة البلد، ١٧.", "(٤) سورة الفرقان، ٦٣."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0033.png"}, {"n": 34, "paras": ["يقول رسول الله ﷺ:", "«إن الله يحب الرفق في الأمر كله»(١)", "«إن الله رفيق يحب الرفق، ويعطي على الرفق ما لا يعطي على العنف، وما لا يعطي على سواه»(٢)", "«إن الرفق لا يكون في شيء إلا زانه، ولا ينزع من شيء إلا شانه»(٣)", "«من أعطي حظه من الرفق فقد أعطي حظه من الخير، ومن حرم حظه من الرفق فقد حرم حظه من الخير»(٤).", "«ألا أنبئكم بما يشرف الله به البنيان، ويرفع الدرجات. قالوا: نعم يا رسول الله. قال: تحلم على من جهل عليك، وتعفو عمن ظلمك، وتعطي من حرمك، وتصل من قطعك»(٥)", "«وجبت محبة الله على من أغضب فحلم»(٦)", "(١) رواه البخاري ومسلم.", "(٢) رواه مسلم.", "(٣) رواه مسلم.", "(٤) رواه الترمذي.", "(٥) رواه الطبراني والبزار.", "(٦) رواه الأصبهاني."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0034.png"}, {"n": 35, "paras": ["أما أفعال رسول الله في ذلك فكثيرة في ذلك:", "عن أنس رضي الله عنه قال: كنت أمشي مع رسول الله ﷺ، وعليه برد نجراني غليظ الحاشية، فأدركه إعرابي، فجذبه بردائه جذبة شديدة، فنظرت إلى صفحة عنق رسول الله ﷺ، وقد أثر بها حاشية الرداء من شدة جذبته، ثم قال: يا محمد مر لي من مال الله الذي عندك.. فالتفت إليه فضحك ثم أمر له بعطاء(١)", "وكان ليهودي اسمه (زيد بن سعنة) دين عند رسول الله ﷺ.. فلما كان قبل محل الأجل بيومين أو ثلاث جاء الى رسول الله وهو في نفر من أصحابه، فأخذ بمجامع قميصه وردائه وقال: يا محمد، ألا تقضيني حقي؟ فوالله ما علمتم بني عبد المطلب إلا مطلاً. فغضب عمر وقال: يا عدو الله، أتقول لرسول الله ما أسمع؟ وتصنع به ما أرى؟ فوالذي نفسي بيده لولا ما احاذر فوته لضربت بسيفي رأسك.. وكان رسول الله ينظر بسكون وتؤدة. فقال: يا عمر، أنا وهو كنا أحوج إلى غير هذا، أن تأمرني بحسن الأداء وتأمره بحسن الطلب. ثم أمره أن يعطيه حقه مع زيادة عشرين صاعاً من تمر. فلما سأل اليهودي عن سبب", "(١) رواه البخاري ومسلم."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0035.png"}, {"n": 36, "paras": ["هذه الزيادة قال له عمر: أمرني رسول الله أن أزيدك مكان ما رعتك. عندها قال اليهودي: يا عمر: لم يكن من علامات النبوة شيء إلا وقد عرفت في وجه رسول الله ﷺ حين نظرت إليه، إلا اثنتين لم أخبرهما منه: يسبق حلمه جهله، ولا تزيده شدة الجهل عليه إلا حلماً وقد اختبرتهما. فأشهدك يا عمر، أني قد رضيت بالله رباً، وبالإسلام ديناً، وبمحمد نبياً.. وأشهدك أن شطر مالي صدقة على أمة محمد ﷺ. ولقد أسلم هذا اليهودي، وشهد مع رسول الله مشاهد كثيرة، ثم استشهد في غزوة تبوك.(١).", "* ومما يروى عن الإمام الشهيد حسن البنا أنه قال: «كونوا كالشجر يرميه الناس بالحجر فيرميهم بالثمر».", "خامساً التيسير لا التعسير", "ومن الصفات التي تساعد الدعاة على الأيغال بدعوتهم بين الناس معالجة الأمور باليسر والتيسير وليس بالعسر والتعسير.. ولما كان الناس أصنافاً شتى فهم كذلك يتفاوتون في", "(١) الرواية للطبراني وابن ماجة."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0036.png"}, {"n": 37, "paras": ["القدرة والاحتمال، فما يطيقه هذا قد لا يطيقه ذاك، وما يتناسب مع هذا قد لا يتناسب مع ذاك. ولذلك كانت القاعدة النبوية: «سيروا على سير أضعفكم».", "ومن أسوأ ما ابتلي به الإسلام في هذا العصر دعاة جبلوا على التعسير في كل شأن، وكأن اليسر ليس من الإسلام في شأن.", "فهم في الصلاة معسرون، وفي الوضوء معسرون، وفي المأكل معسرون، وفي المشرب معسرون، وفي علاقاتهم مع غيرهم معسرون، وفي البيع والشراء معسرون، وفي عمل الدعوة معسرون.. وهم في كل ذلك مخالفون للنهج النبوي الصريح..", "ثم أن هؤلاء لا يتقيدون بمنطق الأولويات، ولا يفرقون في الموقف بين ما هو فرض أو واجب أو سنة. وبين ما هو حرام أو مكروه.. وبين ما فيه نص أو اجتهاد.. فتراهم يكيلون للناس الاتهامات فيكفرون هذا ويفسقون ذاك، وكأن الله قد نصبهم حكاماً على الأمة يقضون فيها بكل ما هو صعب وعسير، فيضيقون سعة الإسلام، ويحجرون مرونة الشريعة، وينفرون الناس من الدين، ألا ساء ما يفعلون.."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0037.png"}, {"n": 38, "paras": ["إن هذا لا يعني أن يترخص الداعية وأن يتساهل ويداهن في إقامة حدود الدين، وإنما أن يستفيد من مساحات المرونة واليسر التي جاء بها الدين نفسه. فإقامة حدود الله أمر لا جدال فيه وليس هو المعني في كلامنا هنا. ويكفي أن نذكر هنا بقوله ﷺ: «أقيموا حدود الله في القريب والبعيد، ولا تأخذكم في الله لومة لائم»(١).", "إن القاعدة النبوية في التعامل مع الآخرين، والتي يجب أن تحكم أسلوب الدعوة والداعية تبدو واضحة جلية في قوله ﷺ: «يسروا ولا تعسروا، وبشروا ولا تنفروا»(٢).", "وفيما ترويه عائشة رضي الله عنها عن رسول الله ﷺ يؤكد هذه القاعدة. قالت عائشة رضي الله عنها: «ما خُيِّر رسول الله ﷺ بين أمرين قط إلا أخذ أيسرهما، ما لم يكن إثماً.. فإن كان إثماً كان أبعد الناس منه. وما انتقم رسول الله ﷺ لنفسه في شيء قط إلا أن تنتهك حرمة الله، فينتقم لله تعالى»(٣).", "ويحض رسول الله ﷺ على لين الجانب وسهولة المعشر ويبين فضل ذلك عند الله فيقول: «ألا أخبركم بمن", "(١) رواه ابن ماجة.", "(٢) رواه البخاري ومسلم.", "(٣) رواه البخاري ومسلم."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0038.png"}, {"n": 39, "paras": ["يحرم على النار أو بمن تحرم عليه النار؟ تحرم على كل هين لين سهل»(١)", "وكان رسول الله ﷺ يعلم هذا الخلق لأصحابه ويدربهم عليه عملياً. فعن أبي هريرة رضي الله عنه، قال: «بال إعرابي في المسجد، فقام الناس إليه ليقعوا فيه. فقال النبي ﷺ: دعوه وأريقوا على بوله سجلا من ماء، أو ذنوباً من ماء.. فإنما بعثتم ميسرين ولم تبعثوا معسرين»(٢).", "إن سماحة الداعية ولينه وسهولة معشره هي التي تفتح مغاليق القلوب وتنفذ به إلى أعماق النفوس. يلامسها بالهداية فتقبل، ويدعوها إلى الخير فتستجيب..", "والخلق هذا يجب أن يغطي مساحة حياة الداعية كلها، وأن يكون ملازماً له في كل شأن من شأنه، وليس أثناء الدعوة فقط..", "ففي بيته يجب أن يكون كذلك.. وفي بيعه وشرائه يجب أن يكون كذلك.. وفي تقاضيه يجب أن يكون كذلك.", "(١) رواه الترمذي.", "(٢) رواه البخاري."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0039.png"}, {"n": 40, "paras": ["ويقرر ذلك رسول الله ﷺ فيقول:", "* «أفضل المؤمنين: رجل سمح البيع، سمح الشراء، سمح القضاء، سمح الاقتضاء»(١)", "* «رحم الله عبداً سمحاً إذا باع، سمحاً إذا اشترى، سمحاً إذا اقتضى»(٢)", "* «وعن حذيفة رضي الله عنه قال: أتى الله بعبد من عباده آتاه مالاً فقال له: ماذا عملت في الدنيا؟ قال: ولا يكتمون الله حديثاً؟ قال يا رب: آتيتني مالاً، فكنت أبايع الناس، وكان من خلقي الجواز(٣)، فكنت أيسر على الموسر وأنظر(٤) المعسر. فقال الله تعالى: أنا أحق بذلك منك، تجاوزوا عن عبدي ، فقال عقبة بن عامر وأبو مسعود الأنصاري: هكذا سمعناه من في رسول الله ﷺ»(٥).", "أعرف أحد الدعاة وهو من كبار العلماء طبعه العسر في كل شيء، صعب التعامل مع كل الناس.. مع الزوجة في", "(١) رواه الطبراني.", "(٢) رواه البخاري.", "(٣) التساهل والتسامح.", "(٤) أمهله.", "(٥) رواه مسلم."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0040.png"}, {"n": 41, "paras": ["البيت، ومع الأولاد. مع الجيران، مع كل الناس. ولقد وصل به الأمر أن عشرات الدعاوى أقيمت عليه أو أقامها على الناس لدى المحاكم.. هذا الإنسان أوتي سعة في العلم ولم يؤت سعة في النفس، ولذلك لم ينفعه علمه، ولم يتمكن من اجتذاب حتى أهل بيته إلى الإسلام واستيعابهم.", "ولقد ذهب الإسلام في دعوته للسماحة والإحسان أبعد من ذلك حتى أوجب أن يكون ذلك مع الحيوان.. فقال رسول الله ﷺ: «إن الله كتب الإحسان على كل شيء. فإذا قتلتم فأحسنوا القتلة، وإذا ذبحتم فأحسنوا الذبحة، وليحد أحدكم شفرته، وليرح ذبيحته»(١).", "سادساً التواضع وخفض الجناح", "ومن أهم وأبرز الصفات التي تجعل الداعية محبوباً في قومه وبيئته، ذا أثر فيهم، وقوامه عليهم صفة التواضع وخفض الجناح..", "(١) رواه مسلم."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0041.png"}, {"n": 42, "paras": ["فالكبر يشكل جداراً وحاجزاً بين الداعية والناس. بل ويجعل الداعية معزولاً عن مجتمعه غير مألوف ممن حوله. وإلى هذا المعنى يشير الرسول ﷺ بقوله: «إن أحبكم إلي أحاسنكم أخلاقاً، الموطئون أكنافاً، الذين يألفون ويؤلفون. وإن أبغضكم إلي: المشاؤون بالنميمة، المفرقون بين الأحبة، الملتمسون للبراء العيب»(١).", "ومظاهر الكبر قد تبدو في صور مختلفة:", "* فقد تبدو في عدم مخالطة الداعية للفقراء أو لعوام الناس وفي حرصه على مخالطة الأغنياء وأصحاب الجاه والسلطان..", "* وقد تبدو في زيادة اهتمامه بلباسه وتأنقه، وفي إعابة التبذل فيمن حوله.", "* وقد تبدو في استنكافه عن القيام بواجب الدعوة (وعظاً، وتوجيهاً، وتدريساً) في عوام من الناس أو قلة قليلة منهم. فهو لا يتحدث إلا إذا كان الجمهور كبيراً، ووسطه رفيعاً؟؟", "* وقد تبدو من خلال تنميق الكلام وتزويق العبارة، والمبالغة في ذلك إلى حد يضيع المعاني ويبطل الأثر..", "(١) رواه الطبراني في الصغير والأوسط."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0042.png"}, {"n": 43, "paras": ["وهذا ما عناه رسول الله ﷺ بقوله: «إن الله يبغض البليغ من الرجال الذي يتخلل بلسانه كما تتخلل البقرة»(١)", "* وقد تبدو في الاعجاب بالعلم، والزهو بالمعرفة، والتحدث عن النفس بعجب، وفي الحرص على منافسة العلماء، ومماراة السفهاء، وهي أخلاق مرذولة نهى رسول الله عنها وحذر منها، فقال: «لا تعلموا العلم لتباهوا به العلماء، ولا تماروا به السفهاء، ولا تحيروا به المجالس، فمن فعل ذلك فالنار النار»(٢). وقال: «إن من أحبكم إلي وأقربكم مني مجلساً يوم القيامة أحاسنكم أخلاقاً. وإن أبغضكم إلي وأبعدكم مني يوم القيامة الثرثارون والمتشدقون والمتفيهقون» للترمذي. إن الداعية المتواضع هو الذي يعيش مع كل الناس، ويستقبل كل الناس، ويكلم كل الناس، ويزور كل الناس، ويحب كل الناس. وهو الذي يخدم الناس ولا يستخدمهم. ويتواصل مع الناس ولا يقاطعهم أو يجافيهم. ألا فليسمع الدعاة إلى رسول الله ﷺ، وليقتدوا", "(١) رواه أبو داود والترمذي.", "(٢) رواه ابن ماجة."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0043.png"}, {"n": 44, "paras": ["بتواضعه وهو سيد ولد آدم وأكرم إنسان.", "فمن أقواله ﷺ:", "* «لا يدخل الجنة من في قلبه مثقال ذرة من كبر»(١).", "* «إن الله أوحى إلي أن تواضعوا، حتى لا يفخر أحد على أحد، ولا يبغي أحد على أحد»(٢).", "* «لا يزال الرجل يذهب(٣) بنفسه حتى يكتب في الجبارين فيصيبه ما أصابهم»(٤).", "ومن تواضعه ﷺ:", "* عن أنس رضي الله عنه، أنه مر على صبيان فسلم عليهم، وقال: كان النبي ﷺ يفعله(٥).", "* وعنه قال: «إن كانت الأمة من إماء المدينة لتأخذ بيد النبي ﷺ فتنطلق به حيث شاءت»(٦).", "* وعن الأسود بن يزيد قال: سئلت عائشة رضي الله عنها: ما كان النبي ﷺ يصنع في بيته؟ قالت: كان يكون في مهنة أهله (يعني في خدمتهم) فإذا حضرت الصلاة خرج إلى الصلاة»(٧).", "(١) رواه مسلم.", "(٢) رواه مسلم.", "(٣) يعتقد أنها عظيمة.", "(٤) رواه الترمذي.", "(٥) رواه الشيخان.", "(٦) رواه البخاري.", "(٧) رواه البخاري."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0044.png"}, {"n": 45, "paras": ["وعن أبي رفاعة تميم بن أسيد رضي الله عنه قال: انتهيت إلى رسول الله ﷺ وهو يخطب، فقلت: يا رسول الله، رجل غريب جاء يسأل عن دينه لا يدري ما دينه. فأقبل عليّ رسول الله وترك خطبته حتى انتهى إليّ، فأتى بكرسي فقعد عليه وجعل يعلمني مما علمه الله، ثم أتى خطبته فأتم آخرها»(١).", "واخرج الطبراني عن أبي أمامة أنه قال: «كان حديث رسول الله ﷺ القرآن. يكثر الذكر. ويكثر الخطبة.. ويطيل الصلاة. ولا يأنف ولا يستكبر أن يذهب مع المسكين والضعيف حتى يفرغ من حاجته».", "وأخرج البيهقي عن أبي موسى أنه قال: «كان الرجل من العوالي ليدعو رسول الله ﷺ بنصف الليل على خبز الشعير فيجيب».", "وأخرج الطبراني عن أبي أمامة قال: «كانت امرأة ترافث الرجال، وكانت بذيئة. فمرت بالنبي ﷺ وهو يأكل ثريداً على طربال (البناء المرتفع) فقالت: انظروا إليه يجلس كما يجلس العبد، ويأكل كما يأكل العبد. فقال النبي ﷺ: وأي عبد أعبد مني؟ قالت: يأكل ولا يطعمني.", "(١) رواه مسلم."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0045.png"}, {"n": 46, "paras": ["قال: فكلي؟ قالت: ناولني بيدك. فناولها. فأكلت، فغلبها الحياء، فلم ترافث أحداً حتى ماتت». وفيما يلي طائفة مما روي عن تواضع الصحابة رضي الله عنهم:", "* أخرج ابن عساكر عن أسلم قال: قدم عمر بن الخطاب رضي الله عنه الشام على بعير، فجعلوا يحدثون بينهم. فقال عمر: تطمح أبصارهم إلى مراكب من لا خلاق لهم».", "* وأخرج الدينوري عن الحسن قال: خرج عمر بن الخطاب رضي الله عنه في يوم حار واضعاً رداءه على رأسه، فمر به غلام على حمار، فقال: يا غلام احملني معك. فوثب الغلام عن الحمار وقال: اركب يا أمير المؤمنين. قال: لا، اركب وأركب أنا خلفك، تريد أن تحملني على المكان الوطيء وتركب أنت على الموضع الخشن، فركب خلف الغلام، فدخل المدينة وهو خلفه، والناس ينظرون إليه».", "* وأخرج ابن سعد وأحمد وابن عساكر عن عبد الله الرومي قال: كان عثمان رضي الله عنه يلي وضوء الليل"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0046.png"}, {"n": 47, "paras": ["بنفسه. فقيل: لو أمرت بعض الخدم فكفوك. فقال لا، إن الليل لهم يستريحون فيه».", "* وأخرج سعد عن ثابت قال. «كان سلمان رضي الله عنه أميراً على المدائن فجاء رجل من أهل الشام من بني (تيم الله) معه حمل تين. فقال لسلمان: تعال احمل (وهو لا يعرفه) فحمل سلمان. فرآه الناس فقالوا: هذا الأمير. قال: لم أعرفك.. فقال له سلمان: لا حتى أبلغ منزلك».", "* وأخرج العسكري عن علي رضي الله عنه قال: «ثلاث من رأس التواضع: ١ - أن يبدأ بالسلام من لقيه ٢ - ويرضى بالدون من شرف المجلس . ٣ - ويكره الرياء والسمعة».", "سابعاً طلاقة الوجه وطيب الكلام", "ومن الصفات التي تفتح للداعية قلوب الناس وتجعله محل قبول عندهم وألفة منهم، طلاقة وجهه وطيب كلامه..", "فالوجه هو عنوان الداعية والمرآة التي تعكس نفسيته وأعماقه. فإن كان متجهماً أوحى بالضيق والتجهم، وإن كان طلقاً مبتسماً أوحى بالبشر والخير.."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0047.png"}, {"n": 48, "paras": ["وليس المقصود بطلاقة الوجه جماله أو حسن تقاسيمه. فقد يكون الوجه جميلاً وليس فيه أثر من الطلاقة، وقد يكون قبيحاً ويفيض أنساً وبشراً. والداعية عليه أن يتعود طلاقة الوجه ولو أن يدرب نفسه على ذلك، وأن يعود نفسه الابتسام كائناً ما كانت ظروفه ضاغطة أليمة.", "إن نجاح الداعية يكمن في قدرته على تكييف نفسه وأن تكون له القوامة عليها وليس العكس. وأن تكون لديه القدرة على التحكم بنفسه حيال الظروف التي يمر بها، وأن يعطي لكل مقام مقالاً.", "أعرف بعض الدعاة يخرجون على الناس والابتسامة تعلو محياهم وقد دفنوا في الأعماق هموماً ومشاكل لا يعلم مداها إلا الله.", "وأعرف آخرين لا يستطيعون السيطرة على أنفسهم حيال أبسط المشكلات والملمات، فترى آثار ذلك بادية في وجوههم ومن خلال تصرفاتهم فتشعر حيال ذلك وكأنك أنت المسيء إليهم؟؟", "سمعت أن أحد الدعاة كان يلقي محاضرة في جمهور غفير في بعض أرياف مصر، وكان قد غادر القاهرة تاركاً"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0048.png"}, {"n": 49, "paras": ["أحد أولاده في مرض شديد. وأثناء المحاضرة دخل القاعة أحد أقرباء الداعية واقترب من المنصة وسلم المحاضر قصاصة من الورق. فما كان من الداعية إلا أن قرأها، ثم تابع محاضرته بشكل طبيعي ودون أن يلحظ الحضور عليه أي أثر. وبعد أن انتهى من حديثه أجاب على كثير من الأسئلة بطلاقة نفس ورحابة صدر. ثم صعق الناس بعد ذلك عندما علموا أن قصاصة الورق التي وصلت الداعية كانت تحمل نبأ وفاة ابنه المريض؟؟", "هذا عن طلاقة الوجه أما عن طيب الكلام فإنه لا يقل أهمية إن لم يكن أكثر أهمية من سواه. فكلام الداعية هو وسيلة الاتصال بالناس ووسيلة التعبير عن المعاني والأفكار. فإن كان الداعية متمكناً من لسانه، متحكماً بكلامه، قادراً على انتقاء الكلم الطيب والتعبير الحسن، كان بالتالي قادراً على كسب قلوب الناس والولوج إلى نفوسهم وذواتهم. وإن كان غير ذلك لا يلقي بالاً إلى ما يخرج من بين شدقيه فقد أقام بينه وبين الناس حاجزاً لا يخترق وسداً لا يمكن النفاذ منه. بل وجعله ذلك مذموماً مكروهاً يتحاشاه الناس ولا يألفونه.", "فمن كتاب الله تعالى قوله *وقل لعبادي يقولوا التي هي أحسن، إن الشيطان"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0049.png"}, {"n": 50, "paras": ["ينزغ بينهم، إن الشيطان كان للإنسان عدواً مبيناً(١).", "* . . وقولوا للناس حسناً(٢).", "* قول معروف ومغفرة، خير من صدقة يتبعها أذى والله غني حليم(٣).", "* يا أيها الذين آمنوا اتقوا الله وقولوا قولاً سديداً(٤).", "* وهدوا إلى الطيب من القول، وهدوا إلى صراط الحميد(٥).", "* وجادلهم بالتي هي أحسن(٦).", "* فقولا له قولاً ليناً لعله يتذكر أو يخشى(٧).", "ومن توجيهات النبوة قوله ﷺ :", "* «لا تحقرن من المعروف شيئاً ولو أن تلقى أخاك بوجه طلق »(٨).", "* «من الصدقة أن تسلم على الناس وأنت طلق الوجه»(٩).", "(١) سورة الإسراء ، ٥٣", "(٢) سورة البقرة، ٨٣ .", "(٣) سورة البقرة، ٢٦٣", "(٤) سورة الأحزاب، ٧٠", "(٥) سورة الحج، ٢٤", "(٦) سورة النحل، ١٢٥", "(٧) سورة طه ، ٤٤", "(٨) رواه مسلم.", "(٩) رواه ابن أبي الدنيا."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0050.png"}, {"n": 51, "paras": ["«لا تحقرن من المعروف شيئاً ولو أن تفرغ من دلوك في إناء المستسقى، ولو أن تكلم أخاك ووجهك إليه منبسط. وإياك وإسبال الإزار فإنه من المخيلة، ولا يحبها الله. وإن امرؤ شتمك بما يعلم فيك فلا تشتمه بما تعلم فيه، فإن أجره لك، وباله على من قاله»(١) «والكلمة الطيبة صدقة»(٢) «موجب الجنة: إطعام الطعام، وإفشاء السلام، وحسن الكلام»(٣) «من كان يؤمن بالله واليوم الآخر فليقل خيراً أو ليصمت»(٤) «إن العبد ليتكلم بالكلمة ما يتبين فيها، يزل بها إلى النار أبعد مما بين المشرق والمغرب»(٥) «إن الرجل ليتكلم بالكلمة من رضوان الله تعالى ما كان يظن أن تبلغ ما بلغت، يكتب الله له بها رضوانه إلى يوم يلقاه. وأن الرجل ليتكلم بالكلمة من سخط الله، ما", "(١) رواه أبو داود والترمذي.", "(٢) رواه البخاري.", "(٣) رواه الطبراني.", "(٤) متفق عليه.", "(٥) متفق عليه."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0051.png"}, {"n": 52, "paras": ["كان يظن أن تبلغ ما بلغت، يكتب الله له بها سخطه إلى يوم يلقاه» (١)", "وإذا كان رسول الله ﷺ، القدوة الحسنة للناس جميعاً فإن الدعاة أولى بهذا الاقتداء من غيرهم.. فلينظر دعاة الإسلام كيف كان رسول الله ﷺ:", "* أخرج الخرائطي والحاكم عن عمرة قالت: سألت عائشة رضي الله عنها، كيف كان رسول الله ﷺ إذا خلا مع نسائه؟ قالت: كالرجل من رجالكم، إلا أنه كان أكرم الناس وألين الناس ضحاكاً بساماً، كذا في الكنزج ٤ ص ٤٧.", "* وأخرج البزار عن جابر رضي الله عنه قال: كان رسول الله ﷺ إذا أتاه الوحي أو وعظ قلت: نذير قوم أتاهم العذاب. فإذا ذهب عنه ذلك رأيت ألطق الناس وجهاً، وأكثرهم ضحكاً، وأحسنهم بشراً.. وعند الطبراني: كان رسول الله ﷺ، من أضحك الناس وأطيبهم نفساً.", "(١) رواه مالك والترمذي."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0052.png"}, {"n": 53, "paras": ["ثامناً الكرم والإنفاق على الناس", "ومن أبرز الشروط اللازمة لنجاح الداعية في دعوته والتي تمكنه من اجتذاب الناس واستيعابهم هي كرمه وإنفاقه على الناس..", "فالكرم والسخاء والعطاء دليل أكيد على كرم وسخاء وعطاء نفس الإنسان فيما البخل والحرص والشح دليل على بخل النفس وحرصها وشحها.", "في كثير من الأحيان يجد الداعية نفسه أمام مشكلات وقضايا لا حل لها بالإنفاق وبذل المال، فإن هو بخل قد يخسر فرصاً لا تفوت، بل قد يتسبب بإحراجات وإساءات بالغة للدعوة نفسها.", "أعرف دعاة، المال عندهم له شأن كبير، وحرصهم عليه يؤدي إلى خسارة كثير من الطاقات كان يمكن أن تكون خيّرة ومعطاءة فيما لو قوبلت بالسماح والكرم والعطاء."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0053.png"}, {"n": 54, "paras": ["أنا أفهم، إنه في سبيل الهداية وعمل الدعوة كل شيء يجب أن يرخص، ذلك أن القيمة الأساسية هي للإنسان الذي سخر الله له ما في السموات وما في الأرض. والمال هو أحد هذه الأسباب ويجب أن يوضع في خدمة الهداية والدعوة وليس العكس.", "* إن إكرام الضيف في الإسلام واجب. ولقد حض رسول الله ﷺ على القيام به فقال: «من كان يؤمن بالله واليوم الآخر فليكرم ضيفه.. الحديث»(١) وهل يتحقق الاكرام من غير إنفاق ومن سخاء نفس ويد؟ إن السخاء الذي جبلت عليه قلوب الرعيل الأول من صحابة الرسول ﷺ هو الذي جعلهم أئمة مهتدين.", "فعن أبي هريرة رضي الله عنه قال: جاء رجل إلى رسول الله ﷺ فقال: إني مجهود. فقال: من يضيف هذا الليلة رحمه الله؟ فقام رجل من الأنصار فقال: أنا يا رسول الله.. فانطلق به إلى رحله، فقال لامرأته: هل عندك شيء؟ قالت: إلا قوت صبياني. قال: فعلليهم(٢) بشيء فإذا أرادوا العشاء فنوميهم، فإذا دخل ضيفنا فأطفئي", "(١) رواه البخاري ومسلم.", "(٢) أي اشغليهم."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0054.png"}, {"n": 55, "paras": ["السراج، وأريه أنا نأكل.. قال: فقعدوا وأكل الضيف، وباتا طاويين. فلما أصبح غدا على رسول الله ﷺ فقال: «قد عجب الله(١) من صنيعكما بضيفكما»(٢).", "ثم ليسمع الدعاة قول رسول الله ﷺ حيث يقول: «الملائكة تصلي على أحدكم ما دامت مائدته موضوعة»(٣)، وقوله: «الخير أسرع إلى البيت الذي يؤكل فيه من الشفرة إلى سنام البعير»(٤).", "* وإن المهاداة بين المسلمين من خلق الإسلام ومن الفعال التي حض عليها الرسول ﷺ. حيث قال: «تهادوا تحابوا». والهدية يهديها الأخ لأخيه هي رسول خير ومظهر حب ووسيلة قربى ومبعث أنس.. تقرب البعيد، وتصل المقطوع، وتشق طريق الدعوة إلى النفوس.. ومن أولى من الداعية بذلك، ومن أحوج منه إلى ذلك؟ ولكن تحقيق ذلك يحتاج إلى بذل وإنفاق وكرم.", "* ثم أن الفضائل كلها التي أمر الإسلام بها تحتاج", "(١) أي عظم ذلك وكبر لديه.", "(٢) رواه مسلم وغيره.", "(٣) رواه الأصبهاني.", "(٤) رواه ابن ماجة."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0055.png"}, {"n": 56, "paras": ["للقيام بها إلى الجود والكرم ويصعب أن يتحقق في غير الجواد الكريم.. فالانفاق على أصحاب الحاجة من الفقراء والمساكين. وكفالة الأيتام.. والإيثار. وإيفاء الكيل. والمواساة. والأخوة. وحق الجار. وإصلاح ذات البين. وغيره، كلها صفات تتعارض والبخل، ولا يمكن أن يتحلى بها البخلاء.", "من هنا جاءت الآيات الكريمة والأحاديث الشريفة تندد بالبخل والبخلاء وتحض على الكرم وتشيد بالكرماء.", "فمن قوله تعالى في البخل: ﴿ولا يحسبن الذين يبخلون بما آتاهم الله من فضله هو خيراً لهم، بل هو شر لهم. سيطوقون بما بخلوا يوم القيامة، ولله ميراث السموات والأرض والله بما تعملون خبير﴾(١) ﴿وأحضرت الأنفس الشح﴾(٢) ﴿ومن يوق شح نفسه فأولئك هم المفلحون﴾(٣). ﴿ولا تجعل يدك مغلولة إلى عنقك ولا تبسطها كل", "(١) سورة آل عمران، ١٨٠", "(٢) سورة النساء، ١٢٨", "(٣) سورة الحشر، ٩"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0056.png"}, {"n": 57, "paras": ["البسط فتقعد ملوماً محسوراً (١). ﴿قل لو أنتم تملكون خزائن رحمة ربي إذاً لأمسكتم خشية الإنفاق، وكان الإنسان قتوراً﴾ (٢).", "وفي وصفه تعالى للمؤمنين: ﴿الصابرين، والصادقين، والقانتين، والمنفقين، والمستغفرين بالأسحار﴾ (٣) ﴿والذين في أموالهم حق معلوم للسائل والمحروم﴾ (٤).", "﴿لا خير في كثير من نجواهم إلا من أمر بصدقة أو معروف أو إصلاح بين الناس. ومن يفعل ذلك ابتغاء مرضات الله فسوف نؤتيه أجراً عظيماً﴾ (٥) ﴿ومما رزقناهم ينفقون﴾ وردت في عشرات الآيات في سياق وصف المؤمنين.", "(١) سورة الإسراء، ٢٩", "(٢) سورة الإسراء، ١٠٠", "(٣) سورة آل عمران، ١٧", "(٤) سورة الذاريات، ١٩", "(٥) سورة النساء، ١١٣."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0057.png"}, {"n": 58, "paras": ["وفي أمره تعالى بالإنفاق: وردت عشرات الآيات بمختلف الصيغ ﴿أنفقوا من طيبات ما رزقناكم﴾، ﴿وأنفقوا مما جعلكم مستخلفين فيه﴾، ﴿أنفقوا مما رزقكم الله﴾، ﴿قل أنفقوا طوعاً أو كرهاً﴾، ﴿وأنفقوا خيراً لأنفسكم﴾، ﴿وأنفقوا في سبيل الله﴾، ﴿لينفق ذو سعة من سعته﴾، ﴿وما لكم ألا تنفقوا﴾.", "ومن قوله ﷺ في البخل: «ما محق الإسلام محق الشح شيء»(١) «شر ما في الرجل: شح هالع، وجبن خالع»(٢) «لا يجتمع شح وإيمان في قلب عبد أبداً»(٣) «خصلتان لا يجتمعان في مؤمن: البخل وسوء الخلق»(٤). «السخي قريب من الله، قريب من الجنة، قريب من الناس، بعيد عن النار.. والبخيل بعيد من الله، بعيد من", "(١) رواه الطبراني.", "(٢) رواه أبو داود وابن حبان.", "(٣) رواه النسائي وابن حبان.", "(٤) رواه الترمذي وغيره."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0058.png"}, {"n": 59, "paras": ["الجنة، بعيد من الناس، قريب من النار. ولجاهل سخي أحب إلى الله من عابد بخيل»(١).", "«ألا أن كل جواد في الجنة حتم على الله، وأنا به كفيل. ألا وإن كل بخيل في النار، حتم على الله، وأنا به كفيل. قالوا: يا رسول الله، من الجواد ومن البخيل؟ قال: الجواد من جاد بحقوق الله عز وجل من ماله. والبخيل من منع حقوق الله، وبخل على ربه. وليس الجواد من أخذ حراماً وأنفق إسرافاً»(٢).", "«السخاء خلق الله الأعظم»(٣)", "«إن الله استخلص هذا الدين لنفسه، فلا يصلح لدينكم إلا السخاء وحسن الخلق، ألا فزينوا دينكم بهما»(٤)", "«أنفق يا بلال ولا تخشى من ذي العرش إقلالاً»(٥)", "(١) رواه الترمذي.", "(٢) رواه الأصبهاني.", "(٣) رواه ابن حبان.", "(٤) رواه الطبراني والأصبهاني.", "(٥) اخرجه الطبراني والبزار."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0059.png"}, {"n": 60, "paras": ["تاسعاً: خدمة الآخرين وقضاء حوائجهم", "ومن شروط نجاح الداعية في دعوته، والتي تمكنه من النفاذ بدعوته في المجتمع الذي يعيش فيه قيامه بخدمة الآخرين والعمل على قضاء حوائجهم.. فالدعوة ليست منبراً لعرض الأفكار والنظريات.. والداعية ليس (مذياعاً) يردد الأفكار المجردة فحسب.. بل إن الدعوة والداعية يجب أن ينتقلا نقلة نوعية تجعلهما يعيشان هموم الناس ويحملان بقسط وافر من هذه الهموم.. وهذا الأمر ليس من قبيل الدعاية والمتاجرة والاستغلال كما هو الشأن لدى الجمعيات التبشيرية وغيرها، وإنما هو مبدأ في صلب المنهج الإسلامي.. لا يصح الإسلام إلا به. وصدق رسول الله ﷺ حيث يقول: «من بات ولم يهتم بأمر المسلمين فليس منهم»(١).", "(١) رواه"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0060.png"}, {"n": 61, "paras": ["في كثير من الأحيان تحول هموم الناس ومشكلاتهم بينهم وبين التلقي. وتصبح هذه الهموم والمشكلات سداً منيعاً في وجه ما يَرُدُّهم من أفكار مجردة ونظريات.. ومن هنا كان من واجب الداعية أن يبادر إلى ازالة العوائق من طريق دعوته، وإلى فتح القنوات الموصلة لأفكاره إلى قلوب الناس وعقولهم..", "وإن كان صحيحاً أن الداعية لن يسع الناس بماله وجهده وخدماته، ولكن ليس من الصحة في شيء اعتباره حائلاً بينه وبين قيامه بما يستطيع. فالمطلوب منه ابتداء القيام ببذل ما يستطيع من جهد، فإن قصر به جهده عوضه وأكمله بحسن الخلق.. وصدق رسول الله ﷺ حيث يقول: «إنكم لن تسعوا الناس بأموالكم فسعوهم بأخلاقكم».", "والإيمان نفسه يجب أن يدفع الداعية إلى أن يحب لغيره ما يحب لنفسه.. وهذا لن يكون إلا بالسعي في شؤونهم وقضاء حوائجهم..", "والأخوة الإسلامية نفسها والتي تقوم على الحب في الله لا يمكن أن تتحقق على أرض الواقع، ويتحقق نقلها من حيز الادعاء إلى حيز التطبيق، إلا من خلال المساعدة والمساندة والاهتمام والسعي وقضاء الحاجة.."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0061.png"}, {"n": 62, "paras": ["وإذا كان رسول الله ﷺ يتبرأ من إنسان يبات شبعان وجاره جائع وهو يعلم، فهو أكثر تبرأ من إنسان يقدر أن يرفع الظلم عن أخيه، أو يقضي حاجته، أو يفرج كربه، أو يزيل همه، ثم لا يفعل؟؟", "إن الداعية بحق هو الذي يعيش لسواه لا لنفسه.. ويكون ديدنه الدوران حول مجتمعه وحول المسلمين وليس حول ذاته. وهو الذي يعمل على توفير الراحة للآخرين ولو على حساب راحته. بل إن الداعية بحق هو الذي تسعده سعادة الآخرين وتشقيه شقاوتهم، يرتاح إذا ارتاحوا، ويطمئن إذا اطمأنوا، ويسعد إذا سعدوا.", "فإذا قامت هذه الوشائج بين الداعية وبين الناس تحقق الوصال والاتصال، وتحقق التأثر والأثر، ونجحت المهمة، وآتت الدعوة أكلها بإذن ربها. وإن كان غير ذلك لم تكن دعوة ولم يكن داعية.", "وكيما يتمكن الداعية من خدمة الناس وقضاء حوائجهم فإن عليه أن يكون قريباً منهم موصولاً بهم مقطوع عنهم. كما أن عليه أن يجالسهم ويحادثهم ويستمع إليهم.", "ولقد كان من صفاته ﷺ إنه كان يجلس إلى الناس"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0062.png"}, {"n": 63, "paras": ["ويستمع لهم حتى وقع الظن لدى البعض وأشاع البعض الآخر من المنافقين أن رسول الله (أُذُن) يستمع إلى هذا ويصدقه ويستمع إلى ذاك ويصدقه - أي تنطلي عليه الأمور - فنزل في ذلك قوله تعالى: ﴿ومنهم الذين يؤذون النبي، ويقولون هو أذن، قل هو أذن خير لكم، يؤمن بالله، ويؤمن للمؤمنين، ورحمة للذين آمنوا منكم والذين يؤذون رسول الله لهم عذاب أليم﴾(١).", "أعرف داعية كثير الجلوس إلى الناس والاستماع إليهم وإلى ما عندهم، حتى غدا بيته مقصداً للناس ومرجعاً لهم. يبثون فيه همومهم، ويستقضون فيه حوائجهم، ويحلون عن طريقه مشاكلهم. ولقد شق هذا الأمر على بعض أصحاب الداعية، واعتقدوا أن في ذلك مضيعة لوقته ومشغلة عن دعوته. ولم يعلم هؤلاء وأولئك - حتى الآن - أن هذا هو ميدان الدعوة العملي، وأن هذا هو الطريق الذي يصلها بالناس وصلاً مباشراً. وإن التوجيه والتوعية اللذين يمكن أن يكونا من خلال ذلك أكثر أثراً من التوجيه العام النظري الذي يكون عادة عن طريق الخطبة والمحاضرة والحديث.", "(١) سورة التوبة ، ٦١"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0063.png"}, {"n": 64, "paras": ["إن من الأسباب الرئيسية لركود الدعوة أو جمودها أو عقمها أحياناً، اكتفاء أصحابها بالإطلال على الناس في المناسبات - بمكتوبات أو مقولات -.", "والدعوة الناجحة هي الدعوة الموصولة بقضايا الناس لأنها ستكون عند ذلك موصولة بقلوبهم ومشاعرهم. إن الفكرة المجردة تدب فيها الحياة وتصبح قضية متحركة إذا ما تجسدت في الواقع وطرحت على أرض الواقع. والفكرة تبقى نظرية وبعيدة ما لم ترتبط أو تحاكي واقعاً معاشاً أو بالتالي تكون معالجة ومتعاملة مع هذا الواقع سلباً أو إيجاباً.", "إن قضايا الناس كثيرة ومتشعبة. فمنها الخاص ومنها العام. ومنها النفسي ومنها الحسي. ومنها التافة ومنها المهم. والداعية يجب أن تكون معالجته لها بحسب الأولويات والأهميات.", "والأمر الذي لا مناص منه ولا فائدة بدونه أن يكون ارتباط الحوائج وبذل المساعي بفكر الداعية ودعوته لا بشخصه، وأن يبدأ بهذا الربط ويسعى له من أول يوم. وإلا كان الاستقطاب حول الشخص وليس حول الفكرة أو الحركة. وهذه قضية مهمة يجب التنبه إليها، والحذر منها قبل أن تصبح باباً للشيطان وبالاً على الدعوة والداعية."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0064.png"}, {"n": 65, "paras": ["وإذا كان المنهج الإسلامي قد حض عموم المسلمين وعامتهم على القيام بقضاء حوائج الناس، فإن دعاة الإسلام معنيون بذلك أكثر..", "* فمما ورد عن رسول الله في الحض على قضاء الحوائج قوله: «المسلم أخو المسلم: لا يظلمه، ولا يسلمه. من كان في حاجة أخيه كان الله في حاجته، ومن فرج عن مسلم كربة فرج الله عنه بها كربة من كرب القيامة، ومن ستر مسلماً ستره الله يوم القيامة»(١).", "«لأن يمشي أحدكم مع أخيه في قضاء حاجته، وأشار بأصبعه، أفضل من أن يعتكف في مسجدي هذا شهرين»(٢).", "«لا يزال الله في حاجة العبد ما دام في حاجة أخيه»(٣).", "* وفي حضه على السعي والسعاية للمسلمين يقول: «الساعي على الأرملة والمساكين كالمجاهد في سبيل", "(١) رواه البخاري ومسلم وأبو داود.", "(٢) رواه الحاكم.", "(٣) رواه الطبراني"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0065.png"}, {"n": 66, "paras": ["الله وكالقائم الليل الصائم النهار»(١). «من كان وصلة (أي شفيعاً موصلاً) لأخيه المسلم إلى ذي سلطان، في مبلغ بر، أو إدخال سرور، رفعه الله في الدرجات العلى من الجنة»(٢). «من لقي أخاه المسلم بما يحب ليسره بذلك سره الله عز وجل يوم القيامة»(٣). «من مشى في حاجة أخيه حتى يثبتها له، أظله الله عز وجل بخمسة وسبعين ألف ملك يصلون له، ويدعون له، إن كان صباحاً حتى يمسي، وإن كان مساء حتى يصبح، ولا يرفع قدماً إلا حط الله عنه بها خطيئة، ورفع له بها درجات»(٤).", "* وفي حضه على إدخال السرور إلى قلب المسلم يقول: «إن من موجبات المغفرة، إدخالك السرور إلى أخيك المسلم»(٥).", "(١) رواه.", "(٢) رواه الطبراني.", "(٣) رواه الطبراني.", "(٤) رواه ابن حبان وغيره.", "(٥) رواه الطبراني."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0066.png"}, {"n": 67, "paras": ["«أفضل الأعمال إدخال السرور على المؤمن، كسوت عورته، أو أشبعت جوعته، أو قضيت حاجته»(١). «من أدخل على أهل بيت من المسلمين سروراً، لم يرض الله له ثواباً دون الجنة»(٢). «أحب الناس إلى الله أنفعهم للناس.. وأحب الأعمال إلى الله عز وجل سرور تدخله على مسلم، تكشف عنه كربة، أو تقضي عنه ديناً، أو تطرد عنه جوعاً. ولأن أمشي مع أخ في حاجة أحب إلي من أن أعتكف في هذا المسجد(٣) شهراً. ومن كظم غيظه ولو شاء أن يمضيه أمضاه ملأ الله قلبه يوم القيامة رضى. ومن مشى مع أخيه في حاجة حتى يقضيها، ثبت الله قدميه يوم تزل الأقدام»(٤).", "وهكذا تتكاثر وتكثر التوجيهات النبوية التي تدعو وتحض على قضاء حوائج المسلمين، وبذل المساعي الخيرة لهم، وإدخال السرور إليهم. ودعاة الإسلام أولى الناس جميعاً في الاقتداء برسول الله ﷺ واتباع سنته..", "(١) رواه الطبراني.", "(٢) رواه الطبراني.", "(٣) يعني مسجد المدينة", "(٤) رواه الأصبهاني."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0067.png"}, {"n": 68, "paras": ["وبذلك نأتي إلى ختام الكلام عن الصفات والشروط التي يحتاجها الداعية ليتمكن من نشر دعوته وتأدية رسالته على أكمل وجه، وليتمكن من استقطاب الناس حول الإسلام واستيعابهم في دعوته.", "ولننتقل بعد ذلك إلى الاستيعاب الداخلي أي ضمن الدعوة وداخل الحركة والتنظيم، والله ولي التوفيق."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0068.png"}, {"n": 69, "paras": ["الاستيعاب الداخلي", "أعني بالاستيعاب الداخلي القدرة والأهلية على الاستيعاب ضمن الدعوة وفي صفوفها. سواء كان ذلك من قبل القيادة أم من قبل الأفراد.", "فإذا كان الاستيعاب الخارجي يحقق اجتذاب الناس إلى الإسلام وإلى الدعوة والحركة وهو مهم، فإن الاستيعاب الداخلي هو الذي يحقق حسن الاستفادة من هؤلاء في عمل الدعوة والحركة.", "إن المرحلة الأولى من العمل أشبه باستخراج المعادن من الأرض وهو عمل (المناجم) والعاملين فيها، في حين تشبه المرحلة الثانية عملية تصنيع هذه المعادن والخامات."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0069.png"}, {"n": 70, "paras": ["وتحويلها عبر (المصانع) إلى أدوات إنتاج مختلفة . . وإذا كان مهما أن نستخرج الخامات البشرية من (منجم) المجتمع الكبير، فمن الأهم التمكن من تحويل هذه الخامات عبر الدعوة إلى طاقات فاعلة على كل صعيد.", "فلنرى كيف يجب أن تتم عملية التحويل والتصنيع هذه.", "إن عملية تحويل خامة بشرية إلى طاقة موجهة وقدرة فاعلة لا بد وأن يتم عبر مراحل ووفق أسس وقواعد - شأن ما يفرض في ذلك على التصنيع المعدني - فما هي هذه المراحل وتلك القواعد والأسس..؟", "المرحلة الأولى: الاستيعاب العقائدي التربوي . . في هذه المرحلة يتعين على الحركة أن تقوم بصياغة الوافدين إليها صياغة نوعية جيدة . . تنقيهم من كل الرواسب الماضية - أفكاراً وممارسات - وتغسل أدمغتهم وعقولهم مما ران عليها أو علق بها من معطيات غير إسلامية . . تصحح عقيدتهم . . تقوّم سلوكهم وأخلاقهم. تهذب أحاسيسهم ومشاعرهم . . توجه رغباتهم وتطلعاتهم . . تحدد"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0070.png"}, {"n": 71, "paras": ["وتوضح أهدافهم وغاياتهم. إن هذه المرحلة هي أهم المراحل على الاطلاق، لأنها بمثابة الأساس الذي سيبنى عليه العمل كله ويقوم عليه البناء كله.. فإن حصل استيهان في هذه المرحلة - وما أكثر ما يحصل - فيترتب عليه خطر كبير وشر مستطير على صعيد الفرد والجماعة.. فالذي يكبر من غير تربية. والذي يرتفع من غير التزام. والذي يتبوأ المسؤوليات بغير جدارة وأهلية، يكون عبئاً على الدعوة وبلاءً عليها في كثير من الأحيان. إن مهمة (القيادة) في هذه المرحلة أن تضع وتهيء كافة الأسباب والأدوات والمناهج اللازمة لعملية الاستيعاب العقائدي هذه، وأن تكون ساهرة مراقبة دقيقة في إجراء هذه العملية. أعرف إنساناً تسلق جدار الدعوة بدون جدارة وأصبح داعية قبل الأوان. وكان يشكو ويعاني من علل وأمراض شتى.. أقلها العجب ومنها الصلف والفظاظة.. ولما علت منزلته وارتفعت درجته وارتفع معها عجبه وصلفه وفظاظته لم يعد من الممكن السيطرة عليه وضبطه، مما أدى أخيراً إلى سقوطه وخسارته."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0071.png"}, {"n": 72, "paras": ["وأعرف غيره ساعدت الدعوة على قتله حين دفعته في طريق وعر قبل أن تعده لسلوكه، ورشحته لأمر لم يكن أهلاً له، واختصرت به مراحل قبل الأوان. فلنتصور كيف كانت النتيجة؟؟", "فعملية التصنيع إن لم تأخذ مداها الكافي، وتتوفر لها كافة الاحتياجات كانت عملية فاشلة، وأدت إلى بروز صناعات مشوهة مما يتسبب بكساد البضاعة والإساءة إلى سمعة المصنع وبالتالي إلى فشله وانهياره؟؟", "وكما أن الصناعات المادية الحسية لا تظهر حقيقتها ومدى جودتها إلا عند التجربة، كذلك الحال مع الدعاة والعاملين فقد لا تظهر معادنهم وتتضح مؤهلاتهم وجداراتهم إلا حين وضعهم على المحك ومن خلال التجربة. وهذا يفرض وضعهم على المحك وتجربتهم قبل تقليدهم المسؤوليات، لتكون تجربتهم على حسابهم وليس على حساب الدعوة..", "ثم إن التغاضي عن علة في فرد واحد، ستدفع إلى التغاضي عن هذه العلة أو غيرها في الصف كله. وبذلك يصبح الصف بلا ضابط..", "صحيح أن الناس يتفاوتون في قدرات التحمل"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0072.png"}, {"n": 73, "paras": ["والالتزام، ولكن هذا لا يجوز أن يدفع إلى التساهل في القواعد والأسس التي تقوم عليها الشخصية الإسلامية.. فمعالم الشخصية يجب أن تكون واحدة، لأنها إن لم تكن كذلك ستؤدي إلى بروز شخصية غير إسلامية.", "إن الاستيعاب التربوي يجب أن يكون قوياً متيناً قائماً على إدراك سليم لأحكام الشريعة، ومعالم الحلال والحرام، ومن ثم التزام بذلك كله.", "والاستيعاب التربوي يجب أن يكون دائماً غير محكوم بمرحلة أو ظرف. فلا يجوز أن يكون قائماً عند المبتدئين ومتعطلاً عند المتقدمين.. ذلك أن المتقدمين أخطر في انحرافهم على الدعوة والصف من المبتدئين، كما أن أسباب الانحراف تكون عندهم أكثر وأوفر. ؟؟", "والاستيعاب التربوي يجب أن يلحظ المتغيرات الحياتية والمراحل الطبيعية والاستثنائية التي يمر بها الأفراد..", "فلا يكون النمط واحداً للكبار والصغار، للمتزوجين وغير المتزوجين، للطلاب والعمال، لمحدودي الثقافة وأصحاب الاختصاصات والخريجين.", "فالاستيعاب التربوي الذي يحتاجه طبيب متخرج غير الذي يحتاجه طالب ثانوي أو صاحب مهنة."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0073.png"}, {"n": 74, "paras": ["والاستيعاب التربوي يجب أن يغطي المساحة التربوية كلها.. فلا يكون فكرياً فحسب أو روحياً فقط.. وإنما يسد كافة الاحتياجات الفطرية لدى الإنسان.", "والاستيعاب التربوي يجب أن يكون موزوناً محكوماً بمقاييس الشرع آخذاً بعزائمه ورخصه، وليس وليد انفعالات وتحكمات شخصية، لأن من شأن ذلك أن يجعل الدعوة الواحدة دعوات والحركة حركات، كما من شأنه أن يمزق الصفوف، كما حصل في العديد من الأقطار والتنظيمات.", "والحقيقة أن أكثر ما تعاني منه الحركة الإسلامية من مشكلات وانقسامات، ومن تساقط للأفراد خلال السير والعمل، ومن بروز ظواهر مرضية في هذا الجانب أو ذاك، سببه الأساسي والأصيل عدم نجاحها في الاستيعاب التربوي، وإخفاقها في تكوين الشخصية الإسلامية وإيجاد الفرد المسلم وفق المواصفات التي وردت في كتاب الله تعالى وسنة نبيه ﷺ.", "فلننظر إلى سنة رسول الله ﷺ في تكوين الشخصية الإسلامية وإيجاد الفرد المسلم، لما لهذا الجانب من أهمية بالغة ومن أثر جذري على سائر الجوانب.."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0074.png"}, {"n": 75, "paras": ["سُنَّة الرسول ﷺ في تكوين المسلم", "لقد نهجت السنّة النبوية الشريفة نهجاً فريداً في تكوين الفرد بما يتناسب مع كمال المنهج الإسلامي والفطرة التي فطر الله الناس عليها . .", "فلم يكن المنهج النبوي في تكوين الفرد ذا طابع روحي بحت يسقط من حسابه الحاجات المادية والعضوية، كما لم يكن منهجاً مادياً محضاً شأن المناهج الوضعية والفلسفات المادية . .", "فسنّة الرسول ﷺ نظرت إلى الإنسان كإنسان، وعاملته كإنسان متكامل الميول والنوازع والحاجات . . فهي لم تتعامل معه كملاك كما أنها لم تعتبره حيواناً كبقية الحيوانات ليس إلا", "قواعد أساسية من السنّة: فيما يلي سنعرض لعدد من القواعد التي بينتها السنّة"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0075.png"}, {"n": 76, "paras": ["النبوية الشريفة في نطاق التكوين والتي من شأنها بناء الفرد بناء سليماً لا تفريط فيه ولا إفراط.", "١ - تغليب الايجابية على السلبية", "فقد كانت سنة رسول الله ﷺ حرباً على السلبية والجمود والتقوقع والرهبانية من أول يوم. فدعوة الإسلام دعوة حية متصلة بالحياة بكل ما تعنيه كلمة الحياة من معنى.", "فهنالك فريق من المسلمين فهموا الإسلام فهماً ضيقاً دفعهم إلى تعطيل طاقة الفرد وحيويته وإنتاجه بحجة العزوف عن الدنيا، والمبالغة في الزهد، والإقبال على الله. فمنهم من اعتزل المجتمع. ومنهم من تخلى عن الوظيفة. بل إن منهم من دفعه غلوه إلى الامتناع عن الصلاة في المساجد العامة بحجة أنها تابعة لمؤسسة رسمية كوزارة أوقاف أو ما شاكل ذلك؟؟", "وهذا النهج فضلاً عن كونه يصطدم اصطداماً مباشراً بطبيعة الإسلام الحركية فإنه يسهل على أعداء الإسلام احتلال مراكز القوى في بلاد المسلمين، والحيلولة دون عودة هذه البلاد إلى قيادة الإسلام ومنهجه في الحياة."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0076.png"}, {"n": 77, "paras": ["وفيما يلي بعض الشواهد النبوية التي ترفض هذه الظاهرة:", "- لقد رؤي أحد المسلمين في عصر النبوة معتزلاً الناس يتعبد على رأس جبل. فأُتي به إلى الرسول ﷺ، فقال له: «لا تفعل أنت ولا أحد منكم. لصبر أحدكم في بعض مواطن الإسلام، خير له من عبادة أحدكم أربعين عاماً».", "- ويقول الرسول ﷺ: «إن الشيطان ذئب الإنسان كذئب الغنم، يأخذ الشاة القاصية والناحية، فإياكم والشعاب، وعليكم بالجماعة والعامة والمسجد» رواه أحمد في مسنده.", "- ويقول الرسول ﷺ: «الذي يخالط الناس ويصبر على أذاهم خير من الذي لا يخالط الناس ولا يصبر على أذاهم».", "٢ - تغليب الاعتدال على التطرف وقاعدة أخرى من قواعد التربية والتكوين في سُنّة الرسول ﷺ، وتتمثل في الحض على الاعتدال والنهي عن التطرف والغلو. ."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0077.png"}, {"n": 78, "paras": ["ففي إطار الالتزام الشخصي بالإسلام يحذر الرسول ﷺ من الغلو والتنطع فيقول: «ألا هلك المتنطعون. ألا هلك المتنطعون»، ويقول: «إن هذا الدين شديد فأوغلوا فيه برفق».", "وفي إطار الدعوة واجتذاب الناس إلى الإسلام يقول الرسول ﷺ: «يسروا ولا تعسروا وبشروا ولا تنفروا» وفي ذلك ترجمة صادقة لقوله تعالى: ﴿ولو كنت فظاً غليظ القلب لانفضوا من حولك﴾، وقوله: ﴿أدع الى سبيل ربك بالحكمة والموعظة الحسنة وجادلهم بالتي هي أحسن﴾.", "وأوضح دليل يمكن أن يساق على نهج اعتدال السنة النبوية الشريفة في تكوين الفرد ما رواه أنس بن مالك رضي الله عنه حيث قال: «جاء ثلاثة رهط إلى بيوت أزواج النبي ﷺ، يسألون عن عبادة النبي ﷺ، فلما اخبروا كأنهم تقالوها، وقالوا أين نحن من النبي ﷺ وقد غفر له ما تقدم من ذنبه وما تأخر. قال أحدهم: أما أنا فأصلي الليل أبدا. وقال الآخر: وأنا أصوم الدهر أبدا، ولا أفطر. وقال الآخر: وأنا أعتزل النساء فلا أتزوج أبدا. فجاء الرسول ﷺ إليهم فقال: أنتم الذين قلتم كذا وكذا؟ أما والله أني لأخشاكم لله وأتقاكم له، لكني أصوم وأفطر،"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0078.png"}, {"n": 79, "paras": ["وأصلي وأرقد، وأتزوج النساء، فمن رغب عن سنتي فليس مني». وعن أبي هريرة رضي الله عنه قال، قال رسول الله ﷺ «إن الدين يسر، ولن يشاد الدين أحد إلا غلبه. فسددوا وقاربوا وأبشروا، واستعينوا بالغدوة والروحة وشيء من الدلجة»، رواه البخاري.", "٣ - القليل الدائم خير من الكثير المنقطع", "ومن القواعد النبوية كذلك الحض على الاستمرارية والديمومة في أعمال البر والخير مهما كانت ضئيلة لأنها تكون بذلك أصيلة ومستطاعة وفي مقدور الإنسان القيام بها من غير عناء..", "وفي أكثر الأحيان تكون الالتزامات القاسية والأعمال الكثيرة التي يقوم بها الإنسان وليدة ردة فعل مؤقتة لا تلبس أن تخبو وتضعف وقد تتلاشى وتدفع بصاحبها في اتجاه معاكس تماماً. كما قد تكون مدخلاً من مداخل العجب إلى النفس، وفي ذلك هلاكها كذلك.", "من هنا كان التوجيه النبوي يؤكد على الاستمرارية في"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0079.png"}, {"n": 80, "paras": ["أعمال البر والخير دونما اهتمام بحجم هذه الأعمال.. بل من هنا كان الحرص على خواتيم الأعمال وليس على مطالعها. فعن عائشة رضي الله عنها أن النبي ﷺ دخل عليها وعندها امرأة. قال: من هذه؟ قالت: هذه فلانة تذكر من صلاتها، قال: «مه، عليكم بما تطيقون، فوالله لا يمل الله حتى تملوا». وعن عبد الله بن عمرو بن العاص رضي الله عنهما قال: قال لي رسول الله « يا عبد الله، لا تكن مثل فلان، كان يقوم الليل فترك قيام الليل» متفق عليه. وفي رواية عن عائشة رضي الله عنها، أن رسول الله ﷺ سئل أي الأعمال أحب إلى الله؟ قال: «أدومها وإن قل». وفي رواية: أن رسول الله ﷺ قال: «سددوا وقاربوا، واعلموا أنه لن يدخل أحدكم عمله الجنة، وأن أحب الأعمال إلى الله أدومها وإن قل» رواه البخاري ومسلم. وفي رواية «كان أحب الأعمال إلى الله عز وجل الذي يدوم عليه صاحبه» رواه مالك والبخاري."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0080.png"}, {"n": 81, "paras": ["- وفي رواية «القليل الدائم خير من الكثير المنقطع».", "٤ - السنة وتغليب الأولوية في التكوين", "ومن سنة الرسول ﷺ في التكوين تغليب الأولوية وتقديم الأهم على المهم..", "فالأخلاق الكريمة يجب أن تكون محصلة العبادة. والعبادة الحسنة يجب أن تأتي نتيجة العقيدة الصحيحة. وهكذا يجب أن تبنى الأعمال على قواعد وأصول ووفق سلم الأولويات.", "أما التكوين الذي لا يلتزم بسلم الأولويات فهو تكوين كيفي مزاجي هش لا يقوم على قواعد راسخة ولا ينهض على أسس قوية متينة، ولذلك يبقى عرضة للتداعي والتساقط وريشة في مهب الريح. وهذا هو الفاصل الجذري والفارق الأساسي بين الأخلاق الإسلامية المبنية على عقيدة التوحيد وبين الأخلاق في مفهوم الفلسفات المادية المبنية على المصلحة.", "من هنا كان النهج النبوي في تكوين الفرد يعتمد على بناء العقيدة أولاً وقبل كل شيء. بل إن هذا النهج جاء"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0081.png"}, {"n": 82, "paras": ["ترجمة عملية لسياق التنزيل القرآني ومراحله وآفاقه. فالقرآن الكريم كان يركز بشكل دائم ومستمر على بناء العقيدة طيلة العهد المكي الذي استمر ما يقرب من ثلاثة عشر عاماً لتكون بعد ذلك سائر الفروع الأخرى من عبادات وتوجيهات وتشريعات مبنية على قاعدة عقائدية صلبة وأسس مبدئية راسخة . . ومن خلال استعراضنا لسياق الآيات القرآنية التكليفية يبدو ترتيب الأولويات واضحاً وثابتاً ومستمراً. من ذلك قوله تعالى : ﴿والعصر إن الإنسان لفي خسر إلا الذين آمنوا وعملوا الصالحات﴾ [العصر ١ - ٣]. ﴿وبشر الذين آمنوا وعملوا الصالحات﴾ [البقرة ٢٥]. ﴿والذين آمنوا وعملوا الصالحات أولئك أصحاب الجنة هم فيها خالدون﴾ [البقرة ٨٢]. ﴿إن الذين آمنوا وعملوا الصالحات وأقاموا الصلاة وآتوا الزكاة لهم أجرهم عند ربهم ولا خوف عليهم ولا هم يحزنون﴾ [البقرة ٢٧٧]. ﴿وعد الله الذين آمنوا وعملوا الصالحات لهم مغفرة"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0082.png"}, {"n": 83, "paras": ["وأجر عظيم﴾ [المائدة ٩].", "- ﴿إذا ما اتقوا وآمنوا وعملوا الصالحات﴾ [المائدة ٩٣].", "- ﴿ليس البر أن تولوا وجوهكم قبل المشرق والمغرب، ولكن البر من آمن بالله، واليوم الآخر، والملائكة، والكتاب، والنبيين، وآتى المال على حبه ذوي القربى واليتامى والمساكين وابن السبيل والسائلين وفي الرقاب، وأقام الصلاة وآتى الزكاة، والموفون بعهدهم إذا عاهدوا والصابرين في البأساء والضراء وحين البأس، أولئك الذين صدقوا وأولئك هم المتقون﴾ [البقرة ١٧٧]. وهكذا تتكاثر الآيات مؤكدة ترتيب الأولويات التكليفية بحسم الأهمية. وتأتي بعد ذلك السنة النبوية الشريفة لتترجم هذه القاعدة من خلال السلوك النبوي في الجانب التكويني:", "- قيل لرسول الله ﷺ أي الأعمال أفضل؟ فقال «العلم بالله عز وجل».", "- وروي: أن رجلاً جاء رسول الله ﷺ فقال: علمني من غرائب العلم. فقال له: ما صنعت في رأس العلم؟ فقال وما رأس العلم؟ فقال ﷺ: هلا عرفت الرب تعالى؟"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0083.png"}, {"n": 84, "paras": ["قال: نعم. قال: فما صنعت في حقه؟ قال: ما شاء الله. قال ﷺ: هل عرفت الموت؟ قال: نعم. قال: فما أعددت له؟ قال: ما شاء الله. قال ﷺ: اذهب فأحكم ما هنالك ثم تعال نعلمك من غرائب العلم»، رواه أبو نعيم وابن عبد البر.", "وقال ﷺ: «أمرت أن أقاتل الناس حتى يقولوا لا إله إلا الله. فإن قالوها، فقد عصموا مني دماءهم وأموالهم» وهذا القول هو ترجمة عملية لقوله تعالى: ﴿إن الله لا يغفر أن يشرك به، ويغفر ما دون ذلك لمن يشاء﴾ [النساء: ٤٨، و١١٦].", "من كل ذلك يتضح أن عملية التكوين يجب أن لا تكون كيفية غير مبنية على أسس أو مقيدة بمراحل وأوليات، لأنها إن كانت كذلك، فهي مخالفة لسنة الرسول ﷺ ومكتوب عليها الفشل من أول الطريق. وما مظاهر التشوه في الشخصية الإسلامية المعاصرة إلا إحدى نتائج الخلل في اتباع السنة في أولويات التكوين.", "ه التكوين من خلال القدوة", "والسنة النبوية الشريفة حضت على أن يكون التكوين بالقدوة، معتبرة أن لسان الحال أوقع من لسان المقال، وأن"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0084.png"}, {"n": 85, "paras": ["أثر العمل أقوى من أثر القول. وصدق الله تعالى حيث يقول: ﴿أتأمرون الناس بالبر وتنسون أنفسكم وأنتم تتلون الكتاب أفلا تعقلون﴾، ويقول: ﴿يا أيها الذين آمنوا لم تقولون ما لا تفعلون. كبر مقتاً عند الله أن تقولوا ما لا تفعلون﴾.", "ورسول الله ﷺ هو المثل الأعلى والأسوة الحسنة للمسلمين في كل زمان ومكان، ولقد كان صلوات الله وسلامه عليه الترجمة العملية للقرآن الكريم. وعندما سئلت عائشة رضي الله عنها عن خلق الرسول قالت: «كان خلقه القرآن».", "ولقد بين الرسول ﷺ أثر القدوة في كثير من توجيهاته وانها دليل الإيمان وثمرته.. وفي ذلك يقول ﷺ:", "- «ليس الإيمان بالتمني ولا بالتحلي ولكن هو ما وقر في القلب وصدقه العمل» رواه الديلمي في مسند الفردوس.", "- «ما آمن بالقرآن من استحل محارمه» رواه الترمذي.", "- «ما من عبد يخطب خطبة إلا الله عز وجل سائله عنها» رواه البيهقي.", "- «مثل الذي يعلم الناس الخير وينسى نفسه، مثل الفتيلة تضيء على الناس وتحرق نفسها» (رواه البزار)."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0085.png"}, {"n": 86, "paras": ["- «كل بنيان وبال على صاحبه إلا ما كان هكذا، وأشار بكفه. وكل علم وبال على صاحبه إلا من عمل به» رواه الطبراني.", "- «إن الرجل لا يكون مؤمناً حتى يكون قلبه مع لسانه سواء، ويكون لسانه مع قلبه سواء، ولا يخالف قوله عمله، ويأمن جاره بوائقه» رواه الأصبهاني.", "وأود أن أسوق هنا قولاً لعلي بن أبي طالب في فضل القدوة وأهميتها يقول رضي الله عنه: «من نصب نفسه للناس إماماً فليبدأ بتهذيب نفسه قبل تهذيب غيره، وليكن تهذيبه بسيرته قبل تهذيبه بلسانه، ومعلم نفسه ومهذبها أحق بالاجلال من معلم الناس ومهذبهم».", "٦ - التكوين الكلي لا الجزئي", "ومن الخصائص التي تميز بها الأسلوب النبوي في تكوين الفرد النظرة الكلية الشمولية.. فسنّة رسول الله ﷺ لم تهتم بجانب من جوانب التكوين، أو بجانب واحد من جوانب الشخصية الإسلامية، وإنما عنيت بالجوانب كلها وبالشخصية كلها..", "فهي لم تهتم بتنمية الفكر على حساب الروح. ولا"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0086.png"}, {"n": 87, "paras": ["بالروح على حساب الجسد. ولا بالجسد على حساب الروح.. ولا بواحدة من هذه على حساب غيرها إنما كان اهتمامها كلياً وشاملاً ومتوازناً، من غير تفريط أو إفراط، ومن غير جنوح أو انحراف، وبدون تطرف أو مبالغة..", "فالمنهج النبوي في التكوين يتناول جوانب الاعداد كلها: الفكرية والنفسية والحركية.. وبذلك يتحقق قيام الشخصية الإسلامية المتكاملة المتوازنة القادرة على الصمود والتصدي والاستمرار والعطاء في كل الظروف..", "أ - ففي معرض عناية السنة النبوية بتكوين (العقلية الإسلامية) وتنمية القدرات الفكرية لدى الفرد نسوق طائفة من الأحاديث الشريفة:", "- «من يرد الله به خيراً يفقهه في الدين» رواه البخاري ومسلم وابن ماجة.", "- «أفضل العبادة الفقه، وأفضل الدين الورع» رواه الطبراني.", "- «من سلك طريقاً يلتمس فيه علماً سهل الله له به طريقاً إلى الجنة - الحديث» رواه الترمذي.", "- «ما اكتسب مكتسب مثل فضل علم يهدي صاحبه إلى هدى، أو يرده عن ردى، وما استقام دينه حتى يستقيم عمله» رواه الطبراني."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0087.png"}, {"n": 88, "paras": ["- «ما عبد الله بشيء أفضل من فقه في الدين، ولفقيه واحد أشد على الشيطان من ألف عابد، ولكل شيء عماد، وعماد هذا الدين الفقه»، رواه البيهقي والدارقطني.", "ب - وفي معرض عناية السنة النبوية بتكوين (النفسية الإسلامية) . ورياضة القلب والروح نسوق نماذج من الأحاديث الشريفة:", "- «لا تميتوا القلوب بكثرة الطعام والشراب، فإن القلب كالزرع يموت إذا كثر عليه الماء».", "- «إن لكل شيء صقالة، وصقالة القلوب ذكر الله. وما من شيء أنجى من عذاب الله من ذكر الله. قالوا: ولا الجهاد في سبيل الله؟ قال: ولو أن يضرب بسيفه حتى ينقطع» رواه البيهقي.", "- «الإنسان عيناه هاد، وأذناه قمع، ولسانه ترجمان، ويداه جناحان، ورجلاه بريد، والقلب منه ملك. فإذا طاب الملك طابت جنوده».", "- «إذا أراد الله بعبد خيراً جعل له واعظاً من قلبه»، «من كان له من قلبه واعظ، كان عليه من الله حافظ» مسند الفردوس.", "- «روحوا عن القلوب ساعة بعد ساعة فإن القلوب إذا كلّت عميت»."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0088.png"}, {"n": 89, "paras": ["- «روحوا القلوب ساعة فساعة»، رواه أبو داوود.", "ج - وفي معرض عناية السنة النبوية بجسد الفرد ليبقى قوياً معافى جلداً قادراً على النهوض بمسؤوليات الحياة وواجبات الرسالة وطاعة الله نسوق نماذج من الأحاديث والتوجيهات النبوية:", "- «ما ملأ آدمي وعاء شراً من بطنه. بحسب ابن آدم لقيمات يقمن صلبه. فإن كان لا بد فاعلاً. فثلث لطعامه، وثلث لشرابه، وثلث لنفسه» رواه الترمذي.", "- «لكل داء دواء فإذا أصاب الدواء الداء برأ بإذن الله عز وجل» رواه مسلم.", "- «نعم يا عباد الله تداووا، فإن الله عز وجل لم يضع داء إلا وضع له شفاء، غير داء واحد، قالوا: ما هو؟ قال: الهرم» رواه أحمد والنسائي.", "- «المؤمن القوي خير وأحب إلى الله من المؤمن الضعيف» رواه مسلم.", "- «علموا أولادكم الرماية والسباحة وركوب الخيل».", "- «تمعددوا، واخشوشنوا، وانتضلوا» رواه الطبراني.", "- «إن لجسدك عليك حقاً»."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0089.png"}, {"n": 90, "paras": ["«الذي يخنق نفسه يخنقها في النار، والذي يطعن نفسه يطعن نفسه في النار، والذي يقتحم يقتحم في النار» رواه البخاري.", "٧ - سلامة البيئة وأثرها في التكوين", "ومن أجل نجاح عملية التكوين عمدت السنة النبوية إلى الاهتمام بسلامة البيئة، بل جعلت لهذه البيئة دوراً أساسياً وفعالاً في تكوين الفرد المسلم تكويناً سليماً ومتكافئاً.", "أ - فالبيئة البيتية (أو العائلية) تعتبر المحضن الأول المعني بعملية التكوين.. والأبوان مسؤولان ابتداء عن إشاعة الأجواء المساعدة في هذه العملية، من خلال التربية النظرية والعملية.. ومنها كانت التوجيهات النبوية واضحة وفاصلة في تبيان مسؤولية الأبوين:", "- «يولد الولد على الفطرة، فأبواه يهودانه، أو ينصرانه، أو يمجسانه».", "- «الرجل راع في أهله ومسؤول عن رعيته، والمرأة راعية في بيت زوجها ومسؤولة عن رعيتها»، رواه البخاري ومسلم."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0090.png"}, {"n": 91, "paras": ["«أدبوا أولادكم وأحسنوا أدبهم» رواه ابن ماجة. «علموا أولادكم وأهليكم الخير وأدبوهم». «مروا أولادكم بامتثال الأوامر واجتناب النواهي، فذلك وقاية لهم من النار» رواه ابن جرير. «أدبوا أولادكم على ثلاث خصال: حب نبيكم، وحب آل بيته، وتلاوة القرآن، فإن حملة القرآن في ظل عرش الله يوم لا ظل إلا ظله» رواه الطبراني.", "ب واختيار الأصدقاء والأصحاب عامل مهم في عملية التكوين. والسنة النبوية الشريفة نبهت إلى ذلك وحذرت من مخالطة الأشرار ومصاحبة المنحرفين، فقال عليه الصلاة والسلام: «المرء على دين خليله، فلينظر أحدكم من يخالل» رواه الترمذي. «مثل الجليس الصالح والجليس السوء كمثل حامل المسك ونافخ الكير. فحامل المسك إما أن يحذيك أي يعطيك أو تشتري منه، أو تجد منه ريحاً طيبة. ونافخ الكير إما أن يحرق ثيابك، أو تجد منه ريحاً منتنة» رواه البخاري ومسلم. «المرء مع من أحب، وله ما اكتسب» رواه الترمذي."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0091.png"}, {"n": 92, "paras": ["- «إياك وقرين السوء فإنك به تعرف» رواه ابن عساكر.", "ج - ولقد حضت السنة النبوية بشدة على ضرورة تنظيف المجتمع من عوامل الفساد درءاً للمفاسد، ومساعدة للفرد على الاستقامة وسلوك سبيل الصالحين وتحقيقاً لقاعدة (درهم وقاية خير من قنطار علاج). وفيما يلي طائفة من التوجيهات النبوية على هذا الصعيد:", "- «مثل القائم على حدود الله والواقع فيها كمثل قوم استهموا على سفينة، فأصاب بعضهم أعلاها وبعضهم أسفلها. فكان الذين في أسفلها إذا استقوا من الماء مروا على من فوقهم، فقالوا: لو خرقنا في نصيبنا خرقاً، ولم نؤذ من فوقنا. فإن تركوهم وما أرادوا هلكوا جميعاً، وإن أخذوا على أيديهم نجوا جميعاً» رواه البخاري والترمذي.", "- «من رأى منكم منكراً فليغيره بيده، فإن لم يستطع فبلسانه، فإن لم يستطع فبقلبه، وذلك أضعف الإيمان» رواه مسلم والترمذي وابن ماجة والنسائي.", "- «إن القوم إذا رأوا المنكر فلم يغيروه عمهم الله بعقاب» رواه النسائي.", "- «لا تزال لا إله إلا الله تنفع من قالها وتصرف عنهم"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0092.png"}, {"n": 93, "paras": ["العذاب والنقمة ما لم يستخفوا بحقها.. قيل وما الاستخفاف بحقها؟ قال: يظهر العمل بمعاصي الله فلا ينكر ولا يغير» رواه الأصبهاني.", "٨ - أثر الثواب والعقاب في التكوين", "ومن الأسباب المساعدة في عملية التكوين، والمتوافقة مع فطرة الإنسان وتكوينه الخلقي المتأثر بمبدأ الثواب والعقاب جاءت السنّة النبوية تطبيقاً عملياً لمبدأ (الجزاء) التي حفل بها القرآن الكريم. وفي مقدمتها قوله تعالى: ﴿ولكم في القصاص حياة يا أولي الألباب لعلكم تتقون﴾. ولكن هذا لا يعني أن يكون التكوين (بالعقوبة) ابتداء وإنما في أعقاب استنفاد كل الوسائط والأسباب. وعلماء التربية المسلمون يرون أنه لا ينبغي للمربي أن يلجأ إلى العقوبة إلا عند الضرورة القصوى، وأن لا يلجأ إلى الضرب إلا بعد التهديد والوعيد وتوسط الشفعاء.. وفي قول لابن خلدون: (من كان مرباه العسف والقهر، سطا به القهر، وضيق على النفس في انبساطها، وذهب بنشاطها، ودعاه إلى الكسل، وحمله على الكذب والخبث خوفاً من انبساط الأيدي بالقهر، وعلمه المكر والخديعة، ولذلك صارت له"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0093.png"}, {"n": 94, "paras": ["هذه عادة وخلقاً، وفسدت معاني الإنسانية التي له». ولذلك كان لا بد من اتباع الأولويات في التكوين ومراعاة الفوارق النسبية والجذرية بين فرد وآخر. .", "- فيكون التكوين ابتداء بالتوجيه.", "- ثم يكون بالملاطفة.", "- ثم يكون بالإشارة والتنبيه.", "- ثم يكون بالتوبيخ.", "- ثم يكون بالهجر والمقاطعة.", "- وأخيراً يكون بالعقوبة الرادعة. وهاكم طائفة من الأحاديث النبوية جاءت في معرض التحذير والعقوبة:", "- «مروا أولادكم بالصلاة وهم أبناء سبع سنين، واضربوهم عليها وهم أبناء عشر»", "- «أقيموا حدود الله في القريب والبعيد ولا تأخذكم في الله لومة لائم» رواه ابن ماجة.", "- «لعن الله الخمر، وشاربها وساقيها ومبتاعها وبائعها وعاصرها ومعتصرها وحاملها والمحمولة إليه» رواه أبو داود.", "- «في هذه الأمة خسف ومسخ وقذف، قال رجل من"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0094.png"}, {"n": 95, "paras": ["المسلمين: يا رسول الله متى ذلك؟ قال: إذا ظهرت القيان، والمعازف، وشربت الخمور» رواه الترمذي.", "- «من شرب الخمر فاجلدوه، فإن عاد في الرابعة فاقتلوه» رواه الترمذي وأبو داود.", "- «إذا استحلت أمتي خمساً فعليهم الدمار: ١ - إذا ظهر التلاعن، ٢ - وشربوا الخمور، ٣ - ولبسوا الحرير، ٤ - واتخذوا القيان، ٥ - واكتفى الرجال بالرجال والنساء بالنساء». رواه البيهقي.", "- «الزنا يورث الفقر» رواه البيهقي.", "- «إذا ظهر الزنا والربا في قرية فقد أحلوا بأنفسهم عذاب الله» رواه الحاكم.", "- «من وجدتموه يعمل عمل قوم لوط فاقتلوا الفاعل والمفعول به» رواه أبو داود.", "وهكذا تتكاثر - في سنة رسول الله ﷺ - أساليب وأسباب التربية والتكوين تكاثر الأمراض والطِباع والعادات والتقاليد والمجتمعات تأكيداً لعظمة الإسلام وإعجازه وقدرته على تغطية كل الاحتياجات، ومعالجة كل النفوس في مختلف الأزمنة والأمكنة. وسنة رسول الله ثابتة ماضية في هذا السبيل لا يضرها من خالفها حتى يأتي أمر الله وصدق."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0095.png"}, {"n": 96, "paras": ["الله تعالى يقول: ﴿وما ينطق عن الهوى إن هو إلا وحي يوحى﴾، وصدق رسوله المصطفى ﷺ حين يقرر: «تركت فيكم شيئين لن تضلوا بعدي ما تمسكتم بهما: كتاب الله وسنتي». المرحلة الثانية: الاستيعاب الحركي: والمقصود بالاستيعاب الحركي قدرة الحركة على استيعاب أفرادها والمنتظمين فيها والمنتمين إليها حركياً. كما أن المقصود منه كذلك استيعاب الحركة لأفرادها للشؤون والأصول والقواعد الحركية. الأول: (ما يتعلق باستيعاب الحركة لأفرادها). استيعاب الحركة لأفرادها هو الشرط الأول والأساسي لنجاحها. فكم من حركة تضم الآلاف من الناس ولكن من غير استيعاب لهم واستفادة من طاقاتهم وإمكانياتهم، مما يجعلها عديمة الأثر محدودة السير. بينما توجد في المقابل حركات تضم بضعة عشرات من الأفراد مستوعبين بالكلية لحركاتهم ومن حركاتهم، أصبحت ذات شأن وأثر وفاعلية في المجتمع. فما هي الشروط التي تمكن الحركة من استيعاب أفرادها: الشروط الأول: أن تكون قد نجحت ابتداء في عملية"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0096.png"}, {"n": 97, "paras": ["التكوين ومرحلة التربية، لأن استيعابها للأفراد حركياً يجب أن يسبقه الاستيعاب التربوي. والبناء الحركي يجب أن يسبقه بناء تربوي، فإن لم يتحقق ذلك أصبح البناء الحركي عملية غير مضمونة النتائج والعواقب..", "الشرط الثاني: أن تكون الحركة قد اكتملت لديها الطاقات والامكانيات اللازمة لعملية الاستيعاب هذه، كالقدرات التنظيمية، والتربوية، والتخطيطية، والفكرية، والسياسية، الخ.", "فالحركة - كل حركة - تبقى قاصرة ومحدودة وضعيفة حتى تتمكن من إكمال بنيتها وبالتالي إنضاج هذه البنية. وحتى تتمكن من توفير الأجهزة والبدائل اللازمة لكل جانب من جوانب العمل. وعندما تتمكن من ذلك تصبح حركة أصيلة قادرة على انجاز عملية الاستيعاب الخارجي والداخلي بنجاح وإتقان..", "إن التفسير الصحيح لتعثر الحركة أحياناً وتخبطها كونها لا تزال في طور النمو والبناء ولم تصبح بعد قادرة على القيام بواجباتها والنهوض بمسؤولياتها على الوجه الأكمل.", "الشرط الثالث: أن تعي حقيقة أفرادها وأن تعرفهم حق المعرفة.. هذه المعرفة التي تكشف لها طاقاتهم،"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0097.png"}, {"n": 98, "paras": ["ميولهم، مواطن القوة والضعف عندهم، والتي من خلالها يمكنها أن تصنفهم وأن تعين لهم وتحدد مهماتهم ومسؤولياتهم، وأن تضعهم في المكان المناسب.", "إن حسن توظيف الإمكانات هو الذي يؤدي إلى الاثمار والنماء والعطاء، أما إذا كان التوظيف عفوياً وكيفياً فإن إنتاجه لن يكون موفوراً ولا مشكوراً.", "الشرط الرابع: أن تقوم بتجنيد كافة أفرادها في العمل وليس فريقاً منهم، أو المتفوقين فيهم. إن ايجاد عمل معين لكل فرد مهما كان بسيطاً ومحدوداً من شأنه أن يضاعف الانتاج، وأن يجنب الحركة الفتن والمشكلات الناجمة عن العاطلين الذين ليس لهم دور ومهمة، والذين يصبحون بؤرة ضعيفة يدخل من خلالها البلاء إلى الجسد كله.", "فالحركة الأصيلة الناجحة هي التي تحرك أصغر الإمكانات فضلاً عن أكبرها، وتحسن الاستفادة من أضعف الأفراد إمكانية فضلاً عن أقواهم، كل في مجاله وضمن إمكاناته..", "ثم أن الحركة بمسيس الحاجة إلى جميع أنواع وأصناف الإمكانات. واكتفاؤها بنمط معين من الامكانيات"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0098.png"}, {"n": 99, "paras": ["يعرضها للفشل والإخفاق..", "فالذين يخططون قد لا يحسنون التنفيذ، أو أن من المستحسن أن لا يتولون ذلك. والذين يشتغلون في التربية قد لا يحسنون العمل السياسي أو العمل العسكري أو العمل الرياضي أو العمل الاجتماعي.. وتوزيع المهمات على المجموعة كلها أفضل بكثير من حصرها في نطاق ضيق..", "إن حصر المهمات والمسؤوليات في عدد محدود من الأفراد له كثير من النتائج السيئة. ويكفي من ذلك أنه يعرض الحركة للانهيار لدى أقل محنة أو مكروه يصيب القيادة، لأنه يحول دون توافر البدائل، ويبقي الأفراد متفرجين. وبدل أن تكسبهم الأيام خبرة وتجربة وقدرة على تحمل المسؤولية وتجشم الصعاب واقتحام العقبات، يصابوا بالبلادة في الحركة والتفكير، وباللامبالاة واللاشعور بالمسؤولية ويصبحوا كلاً وعبئاً على الحركة بدل أن يحملوا أعباءها وأثقالها.", "الشرط الخامس: أن تقوم الحركة بتوظيف القدرات بشكل جماعي وليس بشكل فردي.. إن من أخطر الأمراض التي تعاني منها الحركة ويعاني منه العمل الإسلامي النزعة"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0099.png"}, {"n": 100, "paras": ["الفردية في العمل أو بتعبير آخر قيام العمل على كاهل الأفراد لا الأجهزة.. وهذا بالتالي يجعل العمل مرتبطاً بالفرد متأثراً بطبيعته مرتهناً لإمكانياته وطاقاته، محكوماً بأفكاره وتصوراته واجتهاداته، مما يجعله عرضة وباستمرار للتعثر والتوقف، وللانحراف والتشوه، كما يعرض القائم به للغرور والانتفاخ، ويجعله في الحركة في موقع الاملاء عليها والتحكم فيها، لشعوره بأنه ثغرة لا يسدها غيره، وبأنه يقدم أكثر مما يقدم سواه، وأن الحركة لا تملك حياله شيئاً، وأنه لا عوض عنه ولا بديل..", "الثاني (وما يتعلق باستعابها هي الحركي). إن الدعوة - قيادة وأفراداً - بحاجة إلى الاستيعاب الحركي ابتداء.. والقيادة يجب أن تكون معنية بذلك قبل غيرها، وفاقد الشيء لا يعطيه..", "فما هي الجوانب التي يجب أن تستوعبها الدعوة ويستوعبها الداعية في النطاق الحركي:", "أولاً الاستيعاب الكامل والصحيح للأهداف والوسائل. وكل لبس أو تشوه أو تناقض في التصور للأهداف والوسائل يترتب عليه خلاف بين العاملين، وتباين في تقدير"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0100.png"}, {"n": 101, "paras": ["الأمور، وخروج عن الخط وانحراف عن الهدف. فما يترتب على الاعتقاد بأن الهدف (تغييري) يختلف جذرياً عما يترتب عن كونه (إصلاحي) وتقييم ودراسة الأمور - كل الأمور أهمها وأبسطها، والحكم عليها وتحديد المواقف منها - يختلف بين أن ينظر إليها بهذا المنظار أو ذاك. ولهذا كان لا بد من تحديد واستيعاب.", "ثانياً الاستيعاب الكامل والصحيح للتنظيم وطبيعته. فعدم وضوح الشؤون التنظيمية يؤدي إلى عدم معرفة الحقوق والواجبات، وإلى عدم التعامل وفق القواعد والأصول، وإلى التجاوزات والفرديات، وإلى تصادم الصلاحيات، وإلى نشوء الحساسيات، إلى ما لا نهاية له من النتائج الوخيمة المدمرة.. وليس المهم أن يكون هذا الاستيعاب نظرياً من غير تطبيق وتنفيذ، فالتنفيذ هو الذي يجعل (حركة التنظيم) فاعلة فتتلاشى الفوضى والتعديات والتجاوزات وما يترتب على ذلك كله. فإذا عرفت طبيعة وصلاحية جهاز من الأجهزة أصبح من الخطأ الكبير طرح ما ليس من طبيعته وصلاحيته عليه.."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0101.png"}, {"n": 102, "paras": ["وإذا تحددت صلاحية فرد أصبح من الخطأ تجاوزها منه أو عدم التزامها من سواه . .", "أذكر أن منطقة من مناطق العمل كانت تعاني جموداً كبيراً بينما تشهد المناطق الأخرى نمواً وانتشاراً ملحوظين . . وبعد البحث والتدقيق تبين أن الجهاز المشرف على العمل والمسؤول عن المنطقة يعاني مشكلة تنظيمية تتمثل في (تجاوزه لصلاحياته) . . فبدل أن يكون اهتمامه بشؤون منطقته، كان يتجاوز ذلك إلى الاهتمام بشؤون العالم الإسلامي كله، فينسى ما هو مسؤول عنه، ويترك ما هو واقع ضمن صلاحيته ومهمته، لينساق وراء العاطفة الإسلامية التي تشده بعيداً عما يجب أن يشد إليه .", "وأذكر أن مكتباً إدارياً تشكل من أفراد لم يسبق لهم أن اطلعوا على النظام الداخلي أو اللوائح التنظيمية للأقسام والتي تحدد طبيعة العمل في كل مجال من المجالات . وبعد البحث والتدقيق تبين أن هؤلاء لم يمروا عبر القنوات التنظيمية المحددة ولم يترقوا في التنظيم وفقاً للقواعد والأصول التي تؤهلهم لمثل هذه المسؤوليات، وعندما حصل فراغ قيادي - لظرف من الظروف - سيقوا إلى الهيجا بدون سلاح . ."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0102.png"}, {"n": 103, "paras": ["من المعروف أن تنفيذ أية مهمة حركية يجب أن تمر بمراحل ليتحقق في النهاية التنفيذ على أكمل وجه، ولتتم الفائدة المرجوة. ومن الإستيعاب التنظيمي مرور هذه المهمة وانتقالها عبر المراحل كلها بشكل جيد أو حسن. وحين تتعثر هذه المهمة أو تتوقف في مرحلة من المراحل أو لا يكون تنفيذها جيداً في إحدى هذه المراحل تكون النتيجة سيئة وغير جيدة.", "أذكر أن لقاء من اللقاءات تقرر فيه إقامة إحتفال جماهيري كبير، ولقد استغرق اللقاء وقتاً طويلاً بحثت فيه كافة العناصر التي تضمن نجاح الإحتفال.. الخطباء. مكان الإحتفال.. ترتيبات الإستقبال.. الترتيبات الأمنية.. مكبرات الصوت.. المقاعد.. بطاقات الدعوة. الخ.", "وبعد أن توزعت الأعمال وتم التنفيذ وجاء موعد الإحتفال كانت المفاجأة مذهلة حيث لم يحضر الخطيب الرئيسي والذي عليه المعول.. وبعد سؤال وجواب تبين أن المكلف بالإتصال بالخطباء وتبليغهم لم يعثر على الرجل في بيته فكلف زوجته بذلك على الهاتف، دون أن يكلف نفسه معاودة الإتصال به مرة أخرى على الأقل، ودون أن يدري أنه بهذا التهاون قد عرض عملاً كبيراً للفشل والبوار..", "وفي إحتفال مماثل كانت المفاجئة المذهلة في قلة"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0103.png"}, {"n": 104, "paras": ["الحضور. حيث تبين فيما بعد أن أكداساً من الدعوات الحائطية واليدوية لاتزال في الجوارير ولم توزع على الناس. وأذكر فيما أذكر أن مجموعة من طلبات منح الدراسة كانت قد قدمت من قبل أصحابها إلى أحد المختصين بهذا الشأن. وبدل أن يبادر هذا إلى إجراء ما يلزم ومن ثم تحويلها إلى من يليه في هذا الشأن، وهكذا حتى تبلغ المنتهى، فقد ألقى بها في احد الادراج. وكانت النتيجة أن مر الوقت وفاتها القطار وضاعت سنة كاملة من عمر أصحابها، والذين كانوا ينتظرون وصول القبول دون أن يعلموا أن طلباتهم لاتزال ملقية كالمهملات في الجارور.", "الثالث: (الاستيعاب الكامل لطبيعة الأصدقاء والأعداء ولما يقتضيه ذلك):", "إن من الخطأ الشنيع والخطورة البالغة على الدعوة وعلى الداعية الجهل وعدم المعرفة بطبيعة الأصدقاء والأعداء، وبما يميز الصديق من العدو، وبأهداف كل منهما ووسائله ومبادئه وأدواته وخططه وتحركاته وسياساته ورجاله قيادة وأفراداً.", "فالحركة التي لا تعرف ما يجري حولها، ولا تحسن تصنيف الناس من حولها، حركة فاشلة مكتوب عليها الإخفاق، معرضة للتصفية والسحق من قبل أعدائها.", "أعرف دعاة يحاربون الشيوعيين وهم لا يعرفون شيئاً عن"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0104.png"}, {"n": 105, "paras": ["الشيوعية.. وآخرون يغازلون القوميين وهم لا يفقهون شيئاً عن القومية. وآخرون وآخرون يصادقون أو يعادون ويحاربون أو يهادنون من غير معرفة واستيعاب لحقيقة هؤلاء أو أولئك، ولأساليب هؤلاء أو أولئك..", "كما أعرف البعض الآخر ممن لا يقيمون وزناً لصديق أو عدو، ولا يكلفون أنفسهم عناء إستجلاء الآفاق، أو إستكشاف ورصد التحركات من حولهم، معتبرين ذلك جرأة وإقداماً، وهو في الحقيقة جهل بطبائع الأمور وإحتياجاتها، ونحر للدعوة وتدمير لها..", "إن الحركة الإسلامية تعيش في عصر تكاثر فيه الأعداء، وتعددت وتنوعت أساليب المكر، فإن لم تتبين طريقها، وتتثبت من مواطىء أقدامها، وتتوسل بالحيطة والحذر، مع العمل والإقدام والجرأة، فستتعرض للسقوط في منتصف الطريق دون أن تحفظ الظهر أو تبلغ الهدف..", "الرابع: (الاستيعاب الكامل لمختلف جوانب العمل وطبائعها وإحتياجاتها):", "فالذي يحقق نفاذ الدعوة إلى كافة قطاعات المجتمع إستيعاب الدعاة لطبيعة هذه الجوانب، وتحديدهم للنهج والأسلوب الذي يصلح لكل جانب."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0105.png"}, {"n": 106, "paras": ["فلا بد من دراسة وتحليل وتفكير وابتكار وتجديد وتنويع. ولا بد من الإستفادة من الظرف والحدث والمناسبة. ولا بد من المراجعة والمحاسبة ونقد الذات وإستكشاف العيوب والأخطاء.", "صحيح أن المبادىء التي يجب ان تعطى وتلقن للجميع يجب أن تكون بالنتيجة واحدة.. ولكن لبلوغ هذه النتيجة الواحدة يحتاج الدعاة إلى سلوك سبل مختلفة، وإتباع أساليب متعددة..", "والداعية الناجح هو الذي يعرف كيف يبدأ ومن أين يبدأ مع ضمان الوصول إلى النتيجة المطلوبة.", "والقطاعات المجتمعية أصبح لكل منها في عصرنا هذا خصائص ومعطيات، وبالتالي شؤون ومشكلات بعضها خاص وبعضها مشترك. فالقطاع الطلابي له شؤونه ومشكلاته وقضاياه. والقطاع العمالي له ما يختص به ويميزه. وكذلك قطاع النساء، والخريجين، والعلماء، والسياسيين، ورجال الأعمال وغيرهم. والمدخل إلى كل قطاع من هذه القطاعات قد يتقارب وقد يتباعد، أو قد يتقارب في جانب ويتباعد في آخر..", "وهذا كله يحتاج من الدعوة والداعية إلى دراسة وتمحيص"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0106.png"}, {"n": 107, "paras": ["واستيعاب كلي لشؤون كل قطاع ومشكلاته، ليتحدد بنتيجة ذلك النهج والأسلوب الذي يحتاجه ويصلح له.. وبغير ذلك يصبح عمل الدعوة خبط عشواء..", "أذكر أن موضوع التصنيف هذا طرح في أحد مراكز العمل، فلم يلق قبولاً وتجاوباً من عدد من الدعاة والعاملين.. حيث أصر هؤلاء على إلغاء الأقسام وحصر العمل بقسم واحد، بحجة أن ما يجب إعطاؤه واحد فلا داعي للتعدد الذي من شأنه تبديد الطاقات فضلاً عما يتسببه من تصادم للصلاحيات..", "والنتيجة ستكون عدم تمكن الدعوة من النفاذ إلى القطاعات المختلفة ومن ثم الإمساك بها والسيطرة عليها، وإنما الإكتفاء بجذب بعض العناصر من هذا القطاع أو ذاك بصفتهم الفردية. وهذا من شأنه أن يعزل الدعوة والدعاة عن معترك الصراع ويجعلها عديمة الشأن والفاعلية والأثر..", "الخامس: (عدم الإستنكاف شرط للاستيعاب): إن الدعوة حتى تكون مستوعبة للمجتمع، وأن الدعاة حتى يكونوا مستوعبين للناس، بحاجة إلى معالجة ظاهرة الإستنكاف.", "وظاهرة الإستنكاف هذه آخذة في الإتساع والإنتشار في"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0107.png"}, {"n": 108, "paras": ["محيط الدعوة وواقع العاملين للإسلام يوماً بعد يوم.. وفي بعض الأقطار الإسلامية أخذت هذه الظاهرة منحى مخيفاً وطابعاً خطراً.", "فالإستنكاف عن مخالطة الجماهير والتعامل معها بالإسلام ودعوتها إليه من شأنه أن يجعل هذه الجماهير عدوة للإسلام والحركة ويجعلها مسخرة ضد الدعوة والدعاة من قبل أعداء الإسلام.", "والإستنكاف عن العمل السياسي من الدعوة والدعاة بحجة أن محيط العمل السياسي فاسد ويفسد من يلج إليه، وأن السياسة ملعونة ملعون من يمارسها - الى ما هنالك من أقوال ما أنزل الله بها من سلطان - سيجعل سياسة البلد وقيادته وقراراته بيد أعداء الإسلام، وموجهة ضد الإسلام والعاملين له..", "وإستنكاف الحركة في قطر من الأقطار عن المشاركة في الأجهزة المكونة من تيارات مختلفة لمعالجة مشكلة من المشكلات، سيجعل تلك التيارات هي الحاكمة والفاعلة وهي المهيمنة حتى على الشارع المسلم، مسخرة جماهيره لأغراضها وأهدافها، ومحرضة إياه ضد الحركة الإسلامية نفسها.."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0108.png"}, {"n": 109, "paras": ["وإستنكاف العاملين عن التوظف في أجهزة الدولة المختلفة - التربوية والإعلامية والعسكرية وغيرها - بحجة أن نظامها غير إسلامي، سيجعل هذه الدولة بكل أجهزتها ومؤسساتها بؤرة لأعداء الإسلام، مما يعيق أو يحول دون تحقيق أهداف الحركة القريبة والبعيدة، ويجعلها مشلولة مغلولة . .", "والإستنكاف عن الإختلاط بالناس بحجة بعدهم عن الإسلام وسوء أخلاقهم وكثرة إنحرافاتهم، من شأنه أن يزيد المشكلة تعقيداً، ويوسع الهوة بين هؤلاء وبين الإسلام . . وإذا كان الناس مرضى واستنكف الطبيب عن معالجتهم، فإن هذا المرض سوف يستفحل، وسيقتل الطبيب نفسه فضلاً عن المريض.", "ثم إنه ما قيمة الدعوة وما قيمة الدعاة إن كانوا مستنكفين عن خوض عملية التغيير في المجتمع . . وهل يظن هؤلاء أن عملية التغيير يمكن أن تتم من خارج المجتمع وبدون اختراقه والدخول إليه والتأثير فيه والتعامل معه؟", "إن الدعوة حيال هذا الموضوع أمام خيارين لا ثالث لهما:", "الأول: أن تبقى الدعوة دعوة لأصحابها قاصرة عليهم مهتمة بهم دون غيرهم، غير عابئة بالناس وبهدايتهم. وعند"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0109.png"}, {"n": 110, "paras": ["ذلك تكون دعوة (صالحين) غير مصلحين، ودعوة (صفوية) لا جماهيرية. وعليها أن تدرك إن كانت كذلك، أن نهجها هذا مخالف للإسلام ولطبيعة الدعوة، وأن عملها هذا قد لا ينجيها ويعصمها من طغيان الجاهلية وطوفان الفساد مادامت مستنكفة عن العمل لمواجهته ووقفه أو الحد منه.", "الثاني: أن تكون الدعوة للناس كل الناس - المريض منهم قبل المعافى - والمنحرف فيهم قبل المستقيم - تحمل الهداية إلى الجميع، وتحنو على الجميع، وتريد الخير للجميع، وتحرص على الإستفادة من كل طاقة وتوظيفها في خدمة الدعوة ومعركة الإسلام.", "إن عقائدية التغيير الإسلامي يحتاج من الحركة أن تكون (صفوية) قيادة وطليعة، كما أن جذرية التغيير وشموليته يحتاجها إلى تكون (جماهيرية) كذلك.", "أما إن بقيت الحركة تراوح مكانها بعد مرحلة الإصطفاء دون أن تخرج بمن اصطفتهم إلى دنيا الناس، ومن غير أن تدربهم على ذلك، أو تدفعهم إلى تجربة ذلك، أو تقودهم من خلال ذلك فإن مآلها إلى انعزال، وإن أثرها إلى انحسار، كما وأن عناصرها (المحنطة) المستنكفة عن مخالطة الناس والإهتمام بشؤونهم وتبني مشكلاتهم، ورفع ظلاماتهم،"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0110.png"}, {"n": 111, "paras": ["ستصاب بإدبار قبل إقبال، وبتآكل بعد تكامل، لأنها تكون قد فقدت عنصر القوة في معركة (تصارع البقاء) وصدق الله تعالى حيث يقول ﴿وإن تتولوا يستبدل قوماً غيركم ثم لا يكونوا أمثالكم﴾."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0111.png"}, {"n": 112, "paras": ["الفهرس", "الموضوع الصفحة الإهداء ٥ المقدمة ٧ الإستيعاب في الدعوة والداعية ٩", "- ماذا أعني بالإستيعاب؟ ٩", "- تفاوت القدرة على الإستيعاب ١٠", "- الإستيعاب ونجاح الدعوة ١٣", "- الإستيعاب الخارجي والداخلي ١٣", "* الإستيعاب الخارجي ١٥", "- أولاً الفقه في دين الله ١٦", "- ثانياً القدوة الحسنة ٢٢", "- ثالثاً الصبر ٢٧", "- رابعاً الحلم والرفق ٣٣", "- خامساً: التيسير لا التعسير ٣٨.", "- سادساً: التواضع وخفض الجناح ٤٣"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0112.png"}, {"n": 113, "paras": ["٤٩ .. سابعاً: طلاقة الوجه وطيب الكلام", "٥٥ ثامناً: الكرم والإنفاق على الناس", "٦٢ تاسعاً: خدمة الآخرين وقضاء حوائجهم", "٧١ .. الإستيعاب الداخلي", "٧٢ الاستيعاب العقائدي والتربوي", "٧٧ سنة رسول الله في تكوين المسلم", "٧٨. ١ - تغليب الإيجابية على السلبية", "٧٩. ٢ - تغليب الإعتدال على التطرف", "٨١. ٣ - القليل الدائم خير من الكثير المنقطع", "٨٣ ٤ - السنّة وتغليب الأولوية في التكوين", "٨٦. ٥ - التكوين من خلال القدوة", "٨٨. ٦ - التكوين الكلي لا الجزئي", "٩٢ ٧ - سلامة البيئة وأثرها في التكوين", "٩٥ ٨ - أثر الثواب والعقاب في التكوين", "٩٨ الإستيعاب الحركي", "٩٨. الأول ما يتعلق بإستيعاب الحركة لأفرادها", "١٠٢ الثاني ويتعلق بإستيعابها هي الحركي", "١٠٦ الثالث الإستيعاب الكامل لطبيعة الأصدقاء والأعداء", "١٠٧ الرابع الإستيعاب الكامل لمختلف جوانب العمل", "١٠٩ الخامس: عدم الإستنكاف شرط للإستيعاب"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0113.png"}, {"n": 114, "paras": ["من مؤلفات الأستاذ فتحي يكن", "١ - الإستيعاب في حياة الدعوة والداعية.", "٢ - أبجديات التصوّر الحركي للعمل الإسلامي.", "٣ - الإسلام فكرة وحركة وانقلاب.", "٤ - الإسلام والجنس.", "٥ - حركات ومذاهب في ميزان الإسلام.", "٦ - الشباب والتغيير.", "٧ - العالم الإسلامي والمكائد الدولية.", "٨ - قوارب النجاة في حياة الدعاة.", "٩ - كيف ندعو إلى الإسلام.", "١٠ - ماذا يعني انتمائي للإسلام.", "١١ - مشكلات الدعوة والداعية.", "١٢ - نحو حركة إسلامية عالمية واحدة."], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0114.png"}, {"n": 115, "paras": ["منتدى اقرأ الثقافي www.iqra.ahlamontada.com"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0115.png"}, {"n": 116, "paras": ["(blank page — no text recovered)"], "img": "../../../_ocr-work/libocr/yakan-istiaab/pages/0116.png"}]};
